B=Path(__file__).parent
D={i:[] for i in range(1,5)};M={i:[] for i in D}
U=['1788903283590','1788903293848','1788907111960','1788907123074']
C={
'quad':r'이차함수 $y=a(x-p)^2+q$에서 꼭짓점은 $(p,q)$, 대칭축은 $x=p$입니다. $a>0$이면 아래로 볼록하여 축 왼쪽에서 감소하고 오른쪽에서 증가합니다. $a<0$이면 위로 볼록하여 증가와 감소가 반대입니다. $y=ax^2+bx+c$의 축은 $x=-\frac{b}{2a}$이고 $y$절편은 $c$입니다. 함수값은 해당 $x$를 식에 대입한 결과입니다. 완전제곱식으로 고치면 꼭짓점과 최댓값 또는 최솟값을 읽을 수 있습니다.',
'ratio':r'직각삼각형에서 직각 맞은편의 가장 긴 변이 빗변입니다. 예각 $A$를 기준으로 $\sin A=\frac{\text{높이}}{\text{빗변}}$, $\cos A=\frac{\text{밑변}}{\text{빗변}}$, $\tan A=\frac{\text{높이}}{\text{밑변}}$입니다. 기준각을 바꾸면 높이와 밑변이 바뀝니다. 피타고라스 정리 $a^2+b^2=c^2$로 모르는 변을 구할 수 있습니다. 서로 여각인 두 예각에서는 $\sin A=\cos(90^\circ-A)$입니다. $30^\circ,45^\circ,60^\circ$의 직각삼각형 변의 비는 각각 $1:\sqrt3:2$ 또는 $1:1:\sqrt2$에서 구합니다.',
'area':r'삼각형의 넓이는 $\frac12\times\text{밑변}\times\text{높이}$입니다. 높이는 밑변이 놓인 직선까지의 수직거리입니다. 두 변 $a,b$와 그 끼인각 $C$를 알면 높이가 $b\sin C$이므로 넓이는 $\frac12ab\sin C$입니다. 수선을 그어 직각삼각형으로 나누면 삼각비와 피타고라스 정리를 사용할 수 있습니다. 높이가 같은 삼각형의 넓이비는 밑변의 길이비와 같습니다.',
'chord':r'원의 중심에서 현에 내린 수선은 현을 이등분합니다. 반지름 $r$, 중심에서 현까지의 거리 $d$, 현의 절반 길이 $h$는 직각삼각형을 이루므로 $r^2=d^2+h^2$입니다. 같은 원에서 길이가 같은 현은 중심에서의 거리도 같습니다. 현 전체와 절반을 구분하고, 반지름이 여러 부분으로 나뉘면 점의 순서에 맞추어 합 또는 차로 나타냅니다.',
'circle':r'원주각은 원 위의 꼭짓점에서 두 현이 만드는 각입니다. 같은 호에 대한 원주각은 중심각의 절반이며 같은 호를 보는 원주각끼리는 같습니다. 지름에 대한 원주각은 $90^\circ$입니다. 원에 내접하는 사각형의 마주 보는 두 각의 합은 $180^\circ$입니다. 반지름으로 만든 삼각형은 이등변삼각형이므로 두 밑각이 같습니다. 호를 정할 때 각의 꼭짓점이 들어 있지 않은 쪽의 호를 선택해야 합니다.',
 'tangent':r'원 밖의 한 점에서 원에 그은 두 접선의 접점까지의 길이는 같습니다. 접점에서의 반지름은 접선에 수직입니다. 내접원을 가진 삼각형에서 각 꼭짓점의 두 접선 길이를 같은 문자로 놓으면 세 변을 합으로 나타낼 수 있습니다. 내접원의 반지름 $r$와 반둘레 $s$를 알면 넓이는 $rs$입니다. 원에 외접하는 사각형에서는 마주 보는 두 변의 길이의 합이 같습니다.',
'fold':r'종이를 접으면 대응하는 선분의 길이와 각의 크기가 보존됩니다. 접는 선 위의 점은 이동하지 않으므로 접는 선이 대응각을 이등분합니다. 평행한 두 직선에서는 엇각과 동위각이 같습니다. 삼각형의 내각의 합은 $180^\circ$이며, 수선을 그은 뒤 삼각비 또는 피타고라스 정리를 적용하면 길이를 구할 수 있습니다.'}
def add(r,q,o,a,t,obs,st,steps,end,crop=None,reason='',tip='그림의 겉모양보다 주어진 수치와 조건을 먼저 사용하고, 마지막에 구하는 대상을 다시 확인하세요.'):
 n=len(D[r])+1;o=o.split('|');steps=steps.split('|')
 hint=f'**[관찰 단계]**\n{obs}\n\n**[개념 연결]**\n{C[t]}\n\n**[과정 추론]**\n{st} {tip}\n\n**[결론 유도]**\n{end}'
 e='## 문제 풀이\n**문제 내용:** '+q+'\n\n'+'\n'.join(f'- 보기 ${i+1}$: {v}' for i,v in enumerate(o))+'\n\n### 이 문제를 풀기 위해 무엇을 알아야 할까요? (핵심 개념 체크)\n'+C[t]+'\n\n### 어떻게 접근해야 할까요? (풀이 전략)\n'+st+'\n\n### 차근차근 풀어봅시다! (단계별 상세 풀이)\n'+'\n\n'.join(f'**단계 ${i+1}$:** {v}' for i,v in enumerate(steps))+'\n\n정답은 보기 $'+str(a)+'$, '+o[a-1]+'입니다.\n\n### 이런 실수는 하지 마세요! / 더 알아두면 좋아요 (주의점 및 팁)\n'+tip
 D[r].append(dict(question=q,options=o,answer=o[a-1],hint=hint,explanation=e))
 M[r].append(dict(number=n,correctOptionNumbers=[a],imagePath=f'assets/q{n:02}.png' if crop else None,sourceImagePath=f'assets/source-q{n:02}.png',replaced=bool(reason),replacementReason=reason,crop=crop,verification=steps))
add(1,r'이차함수 $y=f(x)$에서 $f(x)=x^2-5x+1$이라 할 때, $f(2)$의 값은?',r'$5$|$-5$|$6$|$-6$|$2$',2,'quad',r'$f(2)$에서 대입할 값은 무엇인가요?',r'식의 모든 $x$를 같은 수로 바꾼 뒤 제곱, 곱셈, 덧셈 순서로 계산하세요.',r'$f(2)=2^2-5\times2+1$입니다.|$4-10+1=-5$입니다.','연산 순서에 맞게 계산한 값은 어느 보기인가요?')
add(1,r'이차함수 $y=2(x+3)^2-1$에서 $x$의 값이 증가할 때 $y$의 값이 항상 감소하는 구간은?',r'$x<3$|$x>3$|$x<-3$|$x>-3$|$x>0$',3,'quad','괄호 안이 영이 되는 위치와 계수의 부호는 무엇인가요?','꼭짓점의 위치를 찾고 포물선의 양쪽에서 높이가 어떻게 바뀌는지 생각하세요.',r'축은 $x=-3$이고 $a=2>0$이므로 아래로 볼록합니다.|축 왼쪽인 $x<-3$에서 $x$가 증가하면 꼭짓점 쪽으로 내려가므로 감소합니다.','감소하는 쪽을 부등식으로 어떻게 나타낼까요?')
add(1,r'다음 중 이차함수 $y=2(x-1)^2+3$의 그래프에 대한 설명으로 옳은 것은?',r'꼭짓점의 좌표는 $(-1,3)$이다.|$y$절편은 $3$이다.|위로 볼록한 그래프이다.|$y=2x^2$을 $x$축 방향으로 $-1$만큼, $y$축 방향으로 $3$만큼 평행이동한 그래프이다.|$y=-2(x-1)^2-3$과 $x$축에 대칭이다.',5,'quad','꼭짓점 형태에서 이동 방향을 읽을 수 있나요?',r'$x=0$을 대입한 값과 함수 전체에 음수를 붙인 식을 비교하세요.',r'꼭짓점은 $(1,3)$이고 $y$절편은 $5$입니다. 아래로 볼록하며 오른쪽으로 $1$, 위로 $3$ 이동했습니다.|$x$축 대칭은 $y$값의 부호를 바꾸므로 $y=-2(x-1)^2-3$입니다.','모든 조건에 맞는 설명은 무엇인가요?')
add(1,r'이차함수 $y=-x^2+4x-4$의 그래프에서 꼭짓점과 $y$절편을 지나는 직선의 방정식을 $y=ax+b$라 할 때, $a-b$의 값은? (단, $a,b$는 상수)',r'$2$|$4$|$6$|$8$|$10$',3,'quad','직선을 정하는 두 점의 좌표를 구할 수 있나요?','완전제곱식으로 꼭짓점을 찾고 두 점의 세로 변화량을 가로 변화량으로 나누세요.',r'$y=-(x-2)^2$이므로 꼭짓점은 $(2,0)$, $y$절편은 $(0,-4)$입니다.|기울기 $a=\frac{0-(-4)}{2-0}=2$, $b=-4$이므로 $a-b=6$입니다.','상수항의 부호에 주의하여 차를 구해 볼까요?')
add(1,r'$x=1$에 대칭이고 $y$절편이 $5$인 이차함수 $y=ax^2+bx+c$가 점 $(3,2)$를 지날 때, $a+b+c$의 값은?',r'$-6$|$-3$|$0$|$3$|$6$',5,'quad',r'축과 $y$절편은 계수에 어떤 조건을 주나요?',r'축에서 $b$를 $a$로 나타내고 주어진 점을 대입하세요.',r'$c=5$, $-\frac{b}{2a}=1$이므로 $b=-2a$입니다.|$9a+3b+5=2$에 대입하면 $3a=-3$, $a=-1$, $b=2$입니다.|$a+b+c=-1+2+5=6$입니다.','구하는 합은 어느 점에서의 함수값과도 같을까요?')
add(1,r'이차함수 $y=ax^2+bx+c$의 그래프가 그림과 같을 때, $a,b,c$의 부호를 바르게 구한 것은?',r'$a<0,b<0,c>0$|$a<0,b>0,c>0$|$a>0,b<0,c>0$|$a>0,b>0,c<0$|$a<0,b<0,c<0$',3,'quad','볼록한 방향, 축의 위치, 세로축과의 교점을 각각 확인했나요?',r'각 그림 정보가 $a$, $-\frac{b}{2a}$, $c$ 중 무엇을 알려 주는지 연결하세요.',r'아래로 볼록하므로 $a>0$입니다.|축이 $y$축 오른쪽이므로 $-\frac{b}{2a}>0$, 따라서 $b<0$입니다.|$y$절편이 양수이므로 $c>0$입니다.','세 부호를 모두 만족하는 보기는 무엇인가요?',(2,160,194,327,326))
add(1,r'그림은 두 이차함수 $y=-x^2-6x-5$와 $y=-x^2-2x+3$을 나타낸 것이다. 두 그래프의 왼쪽 가지와 $x$축, 두 꼭짓점을 잇는 선분으로 둘러싸인 색칠한 부분의 넓이는?',r'$6$|$8$|$10$|$12$|$14$',2,'quad','두 식을 꼭짓점 형태로 고치면 이동 거리와 높이를 알 수 있나요?','같은 높이에서 두 경계의 가로 간격이 일정함을 이용해 직사각형으로 옮겨 생각하세요.',r'두 식은 각각 $y=-(x+3)^2+4$, $y=-(x+1)^2+4$입니다.|오른쪽 그래프는 왼쪽 그래프를 오른쪽으로 $2$ 이동한 것입니다. 색칠한 부분은 높이 $4$에 걸쳐 가로 폭이 항상 $2$인 띠입니다.|왼쪽의 휘어진 부분을 오른쪽으로 옮기면 가로 $2$, 세로 $4$인 직사각형과 넓이가 같아 $8$입니다.','같은 폭과 전체 높이의 곱은 얼마인가요?',(2,167,704,331,825),reason='정답표의 ④(12)는 두 포물선의 이동 거리 2, 높이 4와 불일치. 넓이 8인 ②로 교정하고 색칠한 경계를 본문에 명시.')
add(1,r'그림과 같이 $\angle C=90^\circ$인 직각삼각형 $ABC$에서 $BC=5$, $AC=3$일 때, $\cos A$의 값은?',r'$\frac45$|$\frac54$|$\frac{5\sqrt{34}}{34}$|$\frac{3\sqrt{34}}{34}$|$\frac34$',4,'ratio','기준각에 붙은 직각변과 빗변은 각각 어느 변인가요?','빗변을 먼저 구한 뒤 코사인의 정의를 적용하세요.',r'$AB=\sqrt{5^2+3^2}=\sqrt{34}$입니다.|$\cos A=\frac{AC}{AB}=\frac3{\sqrt{34}}=\frac{3\sqrt{34}}{34}$입니다.','높이가 아닌 기준각에 붙은 변을 사용했나요?',(2,558,190,741,315),reason='정답표는 ③이나 이는 sin A이다. 본문의 cos A에 맞는 ④로 교정.')
add(1,r'$\angle A=90^\circ$인 직각삼각형 $ABC$에서 $A$에서 $BC$에 내린 수선의 발을 $D$, $D$에서 $AB$에 내린 수선의 발을 $E$라 하자. $BE=2$, $EA=1$, $\angle BAD=x$, $\angle CAD=y$일 때, $\cos x+\sin y$의 값은?',r'$\frac{3\sqrt2}{2}$|$\frac{2\sqrt3}{3}$|$\frac{2\sqrt6}{3}$|$1$|$\frac32$',2,'ratio','두 예각의 합과 빗변 위에 나뉜 길이를 확인했나요?','직각삼각형의 높이가 만드는 닮음으로 필요한 길이를 구한 뒤 여각 관계를 쓰세요.',r'$AB=3$이고 $\triangle ADE\sim\triangle ABD$이므로 $AD^2=AE\times AB=3$, $AD=\sqrt3$입니다.|$\cos x=\frac{AE}{AD}=\frac1{\sqrt3}$이고 $x+y=90^\circ$이므로 $\sin y=\cos x$입니다.|합은 $\frac2{\sqrt3}=\frac{2\sqrt3}{3}$입니다.','같은 두 삼각비를 더하고 분모를 유리화하면 얼마인가요?',(2,557,755,740,858))
add(1,r'다음 삼각비의 표를 이용하여 $\sin36^\circ$의 값을 구하면?',r'$0.5878$|$0.6157$|$0.7880$|$0.8090$|$1.3764$',1,'ratio','표에 원하는 각이 없다면 여각은 실려 있나요?','사인과 여각의 코사인이 같다는 성질로 읽을 행과 열을 정하세요.',r'$\sin36^\circ=\cos(90^\circ-36^\circ)=\cos54^\circ$입니다.|표의 $54^\circ$ 행, 코사인 열에서 $0.5878$을 읽습니다.','알맞은 행과 열의 교차점은 어느 보기인가요?',(3,68,151,409,265))
add(1,r'그림은 폭이 $x$인 종이테이프를 $AC$를 접는 선으로 하여 접은 것이다. $\angle ABC=45^\circ$이고 $\triangle ABC$의 넓이가 $32\sqrt2$일 때, $x$의 값은?',r'$2$|$4$|$6$|$8$|$10$',4,'fold','접힌 두 경계선과 원래 평행한 경계선에서 같은 각을 찾았나요?','접는 선의 각 이등분을 이용해 밑변을 폭으로 나타내고 넓이식을 세우세요.',r'접는 성질과 평행선에서 $\angle ACB=\angle BAC=67.5^\circ$이므로 $AB=BC$입니다.|$A$에서 $BC$에 내린 높이는 폭 $x$입니다. $\angle B=45^\circ$이므로 $AB=x\sqrt2$, 따라서 $BC=x\sqrt2$입니다.|$\frac12x\cdot x\sqrt2=32\sqrt2$에서 $x^2=64$, 길이이므로 $x=8$입니다.','넓이식의 양의 해는 얼마인가요?',(3,139,576,351,709))
add(1,r'그림은 호수의 두 지점 $A,B$ 사이의 거리를 구하기 위해 측량한 것이다. $AC=25\sqrt3\,m$, $BC=30\,m$, $\angle ACB=30^\circ$일 때, $AB$의 길이는?',r'$\sqrt{21}\,m$|$2\sqrt{21}\,m$|$3\sqrt{21}\,m$|$4\sqrt{21}\,m$|$5\sqrt{21}\,m$',5,'ratio','수선을 그으면 두 직각삼각형에서 공통인 높이가 생기나요?','한 변의 밑변 방향 성분과 높이를 삼각비로 구하고 남은 밑변 길이를 사용하세요.',r'$B$에서 $AC$에 내린 수선의 발을 $H$라 하면 $CH=30\cos30^\circ=15\sqrt3$, $BH=30\sin30^\circ=15$입니다.|$AH=25\sqrt3-15\sqrt3=10\sqrt3$입니다.|$AB^2=(10\sqrt3)^2+15^2=525$이므로 $AB=5\sqrt{21}\,m$입니다.','마지막 직각삼각형의 빗변은 얼마인가요?',(3,562,192,738,311))
add(1,r'한 변의 길이가 $8$이고 그 양 끝각이 각각 $60^\circ,45^\circ$인 $\triangle ABC$의 넓이는?',r'$8\sqrt2$|$16(\sqrt3-1)$|$8(\sqrt3-1)$|$16(3-\sqrt3)$|$8(\sqrt3+1)$',4,'area','높이를 내리면 밑변이 두 부분으로 나뉘나요?','공통 높이를 문자로 놓고 두 부분의 합이 주어진 밑변과 같다는 식을 세우세요.',r'높이를 $h$라 하면 밑변의 두 부분은 $\frac h{\sqrt3}$와 $h$입니다.|$\frac h{\sqrt3}+h=8$이므로 $h=4(3-\sqrt3)$입니다.|넓이는 $\frac12\times8\times h=16(3-\sqrt3)$입니다.','밑변과 높이를 이용한 마지막 곱은 얼마인가요?',(3,578,605,730,714))
add(1,r'$AB=AC$인 이등변삼각형 $ABC$에서 $AB=3\,cm$, $\angle B=75^\circ$일 때, 삼각형의 넓이는?',r'$3\,cm^2$|$\frac72\,cm^2$|$4\,cm^2$|$2\,cm^2$|$\frac94\,cm^2$',5,'area','같은 두 변 사이의 각을 밑각으로부터 구할 수 있나요?','삼각형의 내각의 합을 이용한 뒤 두 변과 끼인각의 넓이 공식을 쓰세요.',r'$\angle A=180^\circ-75^\circ-75^\circ=30^\circ$입니다.|넓이는 $\frac12\times3\times3\times\sin30^\circ=\frac94\,cm^2$입니다.','넓이 단위까지 적으면 어느 보기인가요?',(4,83,188,227,275))
add(1,r'원의 중심 $O$에서 $AB\perp OC$이고 $M=AB\cap OC$이다. $AM=6$, $MC=3$일 때, 원의 반지름은?',r'$\frac{13}{2}$|$7$|$\frac{15}{2}$|$8$|$\frac{17}{2}$',3,'chord','반지름과 중심에서 현까지의 거리는 얼마나 차이가 나나요?','반지름을 문자로 놓고 직각삼각형의 세 변을 나타내세요.',r'반지름을 $r$라 하면 $OA=r$, $OM=r-3$입니다.|$r^2=6^2+(r-3)^2$에서 $6r=45$이므로 $r=\frac{15}{2}$입니다.','제곱항이 없어지고 남은 일차식을 풀어 볼까요?',(4,163,574,313,716))
add(1,r'중심이 일치하고 반지름이 다른 두 원에서 $AB=BC=CD=4$이다. 두 반지름의 합이 $10$일 때, 반지름의 차는?',r'$\frac{14}{5}$|$\frac{16}{5}$|$\frac{18}{5}$|$4$|$\frac{22}{5}$',2,'chord','두 현의 중점이 같은 점임을 알 수 있나요?','공통 수선 거리의 제곱을 두 피타고라스 식에서 빼세요.',r'큰 현의 절반은 $6$, 작은 현의 절반은 $2$입니다. 중심에서 현까지 거리를 $d$라 하면 $R^2=d^2+36$, $r^2=d^2+4$입니다.|$R^2-r^2=32=(R-r)(R+r)$이고 $R+r=10$이므로 $R-r=\frac{16}{5}$입니다.','주어진 합을 사용해 차를 구하면 얼마인가요?',(4,593,232,724,349))
add(1,r'그림에서 호 $AB$는 원 $O$의 일부이다. $OD$가 $AB$의 수직이등분선이고 $C=OD\cap AB$, $AB=8\,cm$, $CD=2\,cm$일 때, 반지름은?',r'$4\,cm$|$5\,cm$|$6\,cm$|$7\,cm$|$8\,cm$',2,'chord','현 전체 길이를 그대로 직각삼각형의 변에 넣어도 될까요?','반지름과 중심에서 현까지 거리의 차를 이용하세요.',r'$AC=4\,cm$이고 반지름을 $r$라 하면 $OC=r-2$입니다.|$r^2=(r-2)^2+4^2$에서 $4r=20$, $r=5\,cm$입니다.','현의 절반을 넣은 식의 해는 얼마인가요?',(4,550,692,740,824))
add(1,r'원 $O$는 $\triangle ABC$의 내접원이고 $D,E,F$는 접점이다. $AC=8\,cm$, $BC=7\,cm$, $BD=4\,cm$일 때, $AD=x\,cm$의 $x$값은?',r'$2$|$3$|$4$|$5$|$6$',4,'tangent','한 꼭짓점에서 나온 같은 접선 길이를 표시했나요?','알려진 변에서 접선 조각을 차례로 빼세요.',r'$BE=BD=4$이므로 $CE=7-4=3$입니다.|$CF=CE=3$이므로 $AF=8-3=5$입니다. 따라서 $AD=AF=5$입니다.','마지막 같은 접선 길이는 얼마인가요?',(5,177,209,323,367))
add(1,r'반지름이 $12\,cm$인 원 $O$에서 $AB$는 지름이고 $\angle CAB=30^\circ$이다. 현 $BC$와 작은 호 $BC$ 사이의 색칠한 부분의 넓이는?',r'$(24\pi-36\sqrt3)\,cm^2$|$(12\pi-36\sqrt3)\,cm^2$|$(24\pi-18\sqrt3)\,cm^2$|$(12\pi-18\sqrt3)\,cm^2$|$24\pi\,cm^2$',1,'circle','색칠한 부분을 부채꼴에서 어떤 삼각형을 뺀 것으로 볼 수 있나요?','원주각에서 중심각을 구하고 두 넓이를 따로 계산하세요.',r'$\angle BOC=60^\circ$입니다. 부채꼴 넓이는 $\pi\times12^2\times\frac{60}{360}=24\pi$입니다.|$\triangle BOC$의 넓이는 $\frac12\times12^2\times\sin60^\circ=36\sqrt3$입니다.|차는 $(24\pi-36\sqrt3)\,cm^2$입니다.','호와 현 사이의 넓이는 두 결과의 어떤 연산인가요?',(5,191,699,319,820))
add(1,r'$AB$는 반원 $O$의 지름이고 $AC,BD$의 연장선의 교점은 $P$이다. $\angle P=65^\circ$일 때, $x=\angle COD$의 크기는?',r'$38^\circ$|$42^\circ$|$46^\circ$|$50^\circ$|$54^\circ$',4,'circle','교차하는 두 할선이 만드는 바깥 각과 두 호의 관계를 찾을 수 있나요?','삼각형의 외각과 원주각을 이용해 바깥 각을 두 호의 차로 나타내세요.',r'두 할선 사이의 바깥 각은 큰 호와 작은 호에 대한 중심각 차의 절반입니다. 이는 삼각형의 외각에서 두 원주각을 빼서 얻습니다.|따라서 $65^\circ=\frac{180^\circ-x}{2}$이고 $x=50^\circ$입니다.','반원에 해당하는 각에서 무엇을 빼야 할까요?',(5,562,187,724,303))
add(1,r'원 $O$는 $\triangle ABC$의 외접원이고 원 $O^{\prime}$은 내접원이다. 두 반지름이 각각 $3\,cm$, $1\,cm$이고 $\angle C=90^\circ$일 때, 삼각형의 넓이는?',r'$6\,cm^2$|$7\,cm^2$|$5\sqrt2\,cm^2$|$6\sqrt2\,cm^2$|$7\sqrt2\,cm^2$',2,'tangent','직각삼각형의 빗변은 외접원의 반지름과 어떤 관계인가요?','직각삼각형의 내접원 반지름을 세 변으로 나타내어 반둘레를 구하세요.',r'빗변 $c=2R=6$입니다. 두 직각변을 $a,b$라 하면 접선 길이에서 $a+b-c=2r=2$이므로 $a+b=8$입니다.|반둘레 $s=\frac{8+6}{2}=7$이므로 넓이는 $rs=7\,cm^2$입니다.','반지름과 반둘레의 곱은 얼마인가요?',(5,484,691,631,817))
add(1,r'그림과 같이 사각형 $ABCD$에 내접하는 원이 있다. $AB=4\,cm$, $BC=6\,cm$, $\angle A=\angle B=90^\circ$일 때, 사각형의 둘레는?',r'$15\,cm$|$17\,cm$|$18\,cm$|$20\,cm$|$22\,cm$',3,'tangent','높이와 원의 지름, 밑변의 길이가 서로 어떻게 연결되나요?','접선 길이의 합 조건과 기울어진 변에 대한 피타고라스 식을 함께 쓰세요.',r'$AD=t$라 하면 외접사각형의 성질에서 $CD=BC+AD-AB=t+2$입니다.|$CD^2=(6-t)^2+4^2$이므로 $(t+2)^2=(6-t)^2+16$입니다. 풀면 $t=3$, $CD=5$입니다.|둘레는 $4+6+5+3=18\,cm$입니다.','모든 변의 합을 구해 보기와 대조해 볼까요?',(6,145,204,325,330),reason='본문 AB=6은 그림 AB=4, BC=6과 모순. 그림에 맞게 AB=4, BC=6으로 본문 수정. 원본 정답 ③(18)과 일치.')
add(1,r'그림과 같이 겹쳐진 두 직각삼각형 $ABC,DBC$에서 $\angle ABC=\angle BDC=90^\circ$, $\angle BAC=60^\circ$, $\angle DBC=45^\circ$, $DC=\sqrt6$이다. $E=AC\cap BD$일 때, $\triangle EBC$의 넓이는?',r'$3\sqrt3-3$|$3\sqrt3+3$|$6\sqrt3-3$|$6-3\sqrt3$|$3\sqrt3$',1,'area','두 직각삼각형에서 먼저 구할 수 있는 공통 변은 무엇인가요?','공통 밑변을 구한 뒤 교점의 높이를 두 직선의 기울기로 나타내세요.',r'$\triangle DBC$는 직각이등변삼각형이므로 $BC=\sqrt{12}=2\sqrt3$입니다.|$B=(0,0)$, $C=(2\sqrt3,0)$으로 놓으면 $AB=2$, $A=(0,2)$입니다. $BD$는 $y=x$, $AC$는 $y=2-\frac{x}{\sqrt3}$입니다.|교점의 높이는 $h=3-\sqrt3$입니다. 넓이는 $\frac12\times2\sqrt3\times(3-\sqrt3)=3\sqrt3-3$입니다.','밑변과 교점 높이를 곱한 뒤 절반을 취하면 얼마인가요?',(6,170,684,339,799))
add(1,r'정사각형 $ABCD$에서 $E,F$는 각각 $AB,BC$의 중점이다. 그림의 $x=\angle EDF$에 대하여 $\sin x$의 값은?',r'$\frac15$|$\frac25$|$\frac35$|$\frac45$|$\frac{\sqrt5}{5}$',3,'area','변의 길이를 편리하게 정해도 삼각비는 바뀌지 않나요?','작은 삼각형의 넓이를 전체에서 빼서 구하고 두 변과 끼인각의 넓이 공식을 쓰세요.',r'정사각형의 한 변을 $2$라 하면 $DE=DF=\sqrt5$입니다.|$\triangle DEF$의 넓이는 $4-1-1-\frac12=\frac32$입니다.|$\frac12\times\sqrt5\times\sqrt5\times\sin x=\frac32$에서 $\sin x=\frac35$입니다.','같은 넓이를 두 방식으로 나타낸 식을 풀면 얼마인가요?',(6,497,202,662,358))
add(1,r'$PT$는 원의 접선이고 $P,A,B$는 일직선 위에 있다. $AB=BT$, $\angle APT=30^\circ$일 때, $x=\angle BCT$의 크기는?',r'$90^\circ$|$100^\circ$|$110^\circ$|$120^\circ$|$130^\circ$',3,'circle','같은 두 현이 만드는 이등변삼각형에서 같은 각은 무엇인가요?','접선과 현이 만드는 각이 반대쪽 원주각과 같음을 이용하여 삼각형의 각을 연결하세요.',r'$\angle BAT=\angle ATB=\alpha$로 두면 $\angle PBT=180^\circ-2\alpha$입니다.|접선과 현의 각에서 $\angle PTB=180^\circ-\alpha$입니다. $\triangle PBT$의 각의 합으로 $30+(180-2\alpha)+(180-\alpha)=180$, $\alpha=70^\circ$입니다.|내접사각형 $ABCT$에서 $x+\angle BAT=180^\circ$이므로 $x=110^\circ$입니다.','원에 내접하는 사각형의 대각 합을 마지막에 적용하면 얼마인가요?',(6,542,550,737,675))
add(2,r'$y=-3x^2+1$의 그래프를 평행이동하면 완전히 포갤 수 있고 꼭짓점이 $(0,7)$인 이차함수의 식은?',r'$y=-3x^2+7$|$y=3x^2-7$|$y=-3x^2-7$|$y=3x^2+7$|$y=-3x^2$',1,'quad','평행이동해도 바뀌지 않는 계수는 무엇인가요?','꼭짓점 형태에 주어진 좌표를 넣되 볼록한 방향과 폭을 유지하세요.',r'평행이동은 이차항의 계수 $-3$을 바꾸지 않습니다.|꼭짓점이 $(0,7)$이므로 $y=-3(x-0)^2+7=-3x^2+7$입니다.','두 조건을 동시에 만족하는 식은 무엇인가요?')
add(2,r'길이가 $50\,cm$인 끈을 모두 사용하여 세로가 $x\,cm$인 직사각형을 만든다. 넓이가 $154\,cm^2$일 때 가능한 세로 길이들의 합은?',r'$11\,cm$|$14\,cm$|$25\,cm$|$39\,cm$|$50\,cm$',3,'quad','둘레에서 가로와 세로의 합은 얼마인가요?','가로를 세로에 관한 식으로 나타내어 넓이 방정식을 세우세요.',r'가로는 $25-x$이므로 $x(25-x)=154$입니다.|$x^2-25x+154=(x-11)(x-14)=0$이므로 $x=11,14$입니다. 두 길이 모두 가능합니다.|합은 $11+14=25\,cm$입니다.','가능한 두 해를 모두 더했나요?',(1,154,735,299,858))
add(2,r'$y=-2x^2+ax+b$의 그래프가 그림과 같을 때, 상수 $a,b$에 대하여 $a+b$의 값은?',r'$4$|$6$|$8$|$10$|$12$',4,'quad','그림에서 축과 세로축의 교점은 각각 무엇인가요?','축 공식에 이차항의 음수 계수를 정확히 넣으세요.',r'$y$절편에서 $b=6$입니다. 축은 $x=1$이므로 $-\frac{a}{2(-2)}=1$, $a=4$입니다.|$a+b=4+6=10$입니다.','두 상수의 합은 얼마인가요?',(1,607,200,755,369))
add(2,r'이차함수 $y=x^2+ax+b$의 그래프가 그림과 같을 때, 꼭짓점의 좌표는? (단, $a,b$는 상수)',r'$(-1,-8)$|$(-1,-9)$|$(-2,-8)$|$(-2,-9)$|$(-3,-9)$',4,'quad','축과 만나는 두 점의 좌표를 읽었나요?','두 점을 식에 대입하여 계수를 구하고 완전제곱식으로 고치세요.',r'$(0,-5)$를 지나므로 $b=-5$입니다. $(-5,0)$을 대입하면 $25-5a-5=0$, $a=4$입니다.|$y=x^2+4x-5=(x+2)^2-9$이므로 꼭짓점은 $(-2,-9)$입니다.','괄호 안 부호와 꼭짓점의 좌표를 구분했나요?',(1,551,724,722,873))
add(2,r'하루에 $x$개의 제품을 생산할 때 이익금 $y$만 원이 $y=-\frac1{100}x^2+10x-500$의 관계를 만족한다. 하루 이익금이 $2000$만 원이 되려면 몇 개를 생산해야 하는가?',r'$100$개|$250$개|$400$개|$500$개|$1000$개',4,'quad','생산량과 이익금 중 어느 값을 알고 있나요?','주어진 이익을 대입하고 분모를 없앤 뒤 완전제곱식을 찾으세요.',r'$2000=-\frac1{100}x^2+10x-500$입니다.|정리하면 $x^2-1000x+250000=(x-500)^2=0$이므로 $x=500$입니다.','생산량을 원래 식에 대입해 이익금을 확인해 볼까요?',reason='문제지의 양수 제곱항은 해설지 식 및 정답과 불일치. 해설지의 음수 제곱항으로 수정하여 최대 이익을 구하는 원래 의도 보존.')
add(2,r'축이 $x=1$이고 $x$축에 접하며 $y$축과의 교점이 $(0,-3)$인 이차함수의 식은?',r'$y=(x-1)^2-3$|$y=(x-1)^2+3$|$y=-3(x+1)^2$|$y=-3(x-1)^2$|$y=3(x-1)^2$',4,'quad','접한다는 조건은 꼭짓점의 높이를 어떻게 정하나요?','꼭짓점 형태의 식에 세로축 교점을 대입하세요.',r'꼭짓점은 $(1,0)$이므로 $y=a(x-1)^2$입니다.|$(0,-3)$을 대입하면 $a=-3$이므로 $y=-3(x-1)^2$입니다.','접하는 위치와 교점이 모두 맞는 식인가요?')
add(2,r'$y=x^2-4x+a$의 그래프와 $x$축의 교점을 $A,B$라 한다. $AB=6$일 때 상수 $a$의 값은?',r'$-9$|$-5$|$-1$|$4$|$5$',2,'quad','대칭축은 두 교점의 중점인가요?','축에서 좌우 같은 거리만큼 떨어진 두 교점 중 하나를 대입하세요.',r'축은 $x=2$입니다. 두 교점의 간격이 $6$이므로 각각 $x=-1,5$입니다.|$(-1,0)$을 대입하면 $0=1+4+a$, $a=-5$입니다.','다른 교점을 대입해도 같은 상수가 나오나요?',(2,557,235,737,418))
add(2,r'이차함수 $y=2x^2-4x-1$과 일차함수 $y=x-3$의 교점의 좌표를 바르게 구한 것은?',r'$(-\frac12,-\frac72),(1,-2)$|$(\frac12,-\frac52),(2,-1)$|$(\frac32,-\frac32),(3,0)$|$(\frac12,-\frac52)$|$(3,0)$',2,'quad','교점에서는 두 식의 어떤 값이 같나요?','두 식을 같게 놓고 가로좌표를 구한 후 세로좌표도 구하세요.',r'$2x^2-4x-1=x-3$에서 $(2x-1)(x-2)=0$이므로 $x=\frac12,2$입니다.|$y=x-3$에 대입하면 각각 $y=-\frac52,-1$입니다.','해 두 개에 대응하는 좌표를 모두 적었나요?')
add(2,r'$y=x^2-k$가 $x$축과 두 점 $A,D$에서 만나고 $y=ax^2-k$가 $x$축과 두 점 $B,C$에서 만난다. 그림처럼 $BO=CD$가 될 때 $a$의 값은? ($O$는 원점)',r'$\frac14$|$\frac12$|$2$|$4$|$8$',4,'quad','원점에 대한 대칭으로 같은 길이를 찾았나요?','가로좌표를 제곱근으로 나타내고 주어진 선분 관계를 쓰세요.',r'$OD=\sqrt k$, $OC=OB=\sqrt{\frac ka}$입니다.|$BO=CD$에서 $\sqrt{\frac ka}=\sqrt k-\sqrt{\frac ka}$입니다.|$2\sqrt{\frac ka}=\sqrt k$를 제곱하고 $k>0$으로 나누면 $\frac4a=1$, $a=4$입니다.','길이가 양수임을 확인한 뒤 방정식을 풀면 얼마인가요?',(3,117,270,333,433))
add(2,r'$y=-x^2-6x+5$의 그래프를 $x$축 방향으로 $k$만큼 평행이동했더니 감소하는 $x$의 범위가 $x>0$이었다. $k$의 값은?',r'$-6$|$-3$|$0$|$3$|$6$',4,'quad','감소가 시작되는 경계는 대칭축과 어떤 관계인가요?','원래 꼭짓점의 가로좌표에 이동량을 더하세요.',r'$y=-(x+3)^2+14$이므로 원래 축은 $x=-3$입니다.|위로 볼록하므로 이동 후 축 오른쪽에서 감소합니다. 새 축이 $x=0$이므로 $-3+k=0$, $k=3$입니다.','이동 방향과 이동량의 부호가 맞나요?')
add(2,r'다음 이차함수 중 꼭짓점이 제 $4$사분면에 있는 것은?',r'$y=-x^2+2$|$y=3(x+1)^2$|$y=-x^2-2x$|$y=x^2-4x-3$|$y=-x^2+6x+1$',4,'quad','제사분면에서 두 좌표의 부호는 어떻게 되나요?','각 식을 꼭짓점 형태로 고친 뒤 축 위의 점은 사분면에 포함되지 않음을 확인하세요.',r'각 꼭짓점은 차례로 $(0,2)$, $(-1,0)$, $(-1,1)$, $(2,-7)$, $(3,10)$입니다.|가로좌표가 양수이고 세로좌표가 음수인 것은 $(2,-7)$이므로 보기 $4$입니다.','두 부호가 모두 맞는 꼭짓점은 무엇인가요?')
add(2,r'$y=x^2-2ax-b$의 그래프가 $(1,4)$를 지나고 꼭짓점이 직선 $y=-2x+7$ 위에 있을 때, $a-b$의 값은? ($a,b$는 상수)',r'$3$|$5$|$7$|$9$|$11$',4,'quad','한 점을 지나는 조건과 꼭짓점의 위치 조건을 따로 식으로 쓸 수 있나요?','첫 조건에서 한 상수를 없앤 뒤 꼭짓점 좌표를 직선에 대입하세요.',r'$4=1-2a-b$이므로 $b=-2a-3$입니다.|꼭짓점은 $(a,-a^2-b)$입니다. $-a^2+2a+3=-2a+7$에서 $(a-2)^2=0$, $a=2$입니다.|$b=-7$이므로 $a-b=9$입니다.','두 조건을 모두 반영한 상수의 차는 얼마인가요?')
add(2,r'점 $A,B$는 각각 $y=-x^2+2x+3$, $y=-x^2+8x-12$의 꼭짓점이다. 두 그래프의 왼쪽 가지와 $x$축, 선분 $AB$로 둘러싸인 어두운 부분의 넓이는?',r'$6$|$8$|$10$|$12$|$16$',4,'quad','두 포물선이 같은 모양으로 얼마나 이동했나요?','같은 높이에서 띠의 폭이 일정한 점을 이용하여 넓이를 직사각형과 비교하세요.',r'두 식은 $y=-(x-1)^2+4$, $y=-(x-4)^2+4$입니다.|두 왼쪽 가지의 가로 간격은 항상 $3$이고 높이는 $4$입니다. 한쪽 휘어진 부분을 옮기면 직사각형과 같습니다.|넓이는 $3\times4=12$입니다.','일정한 폭과 높이의 곱은 얼마인가요?',(4,124,234,335,397))
add(2,r'정삼각형 $ABC$에서 $AC$의 중점을 $D$, $BD$의 중점을 $E$라 하자. $\angle BCE=\theta$, $\sin\theta=p$일 때, $p^2$의 값은?',r'$\frac3{28}$|$\frac3{14}$|$\frac17$|$\frac37$|$\frac{21}{28}$',1,'area','중선이 수선이 되는 정삼각형의 성질을 쓸 수 있나요?','작은 직각삼각형에서 길이를 구하고 넓이를 두 가지 방식으로 나타내세요.',r'한 변을 $a$라 하면 $CD=\frac a2$, $BD=\frac{\sqrt3a}{2}$, $ED=BE=\frac{\sqrt3a}{4}$입니다.|직각삼각형 $CDE$에서 $CE=\frac{\sqrt7a}{4}$입니다.|$\triangle BCE$의 넓이는 $\frac12BE\cdot CD=\frac{\sqrt3a^2}{16}$이며 동시에 $\frac12BC\cdot CE\sin\theta$입니다. 따라서 $p=\frac{\sqrt3}{2\sqrt7}$, $p^2=\frac3{28}$입니다.','길이의 배율이 약분된 뒤 제곱하면 얼마인가요?',(4,134,782,316,943))
add(2,r'$AB=8$, $BC=5$인 $\triangle ABC$의 넓이가 $10\sqrt2$이다. $\angle B>90^\circ$일 때, $\angle B$의 크기는?',r'$45^\circ$|$105^\circ$|$120^\circ$|$135^\circ$|$150^\circ$',4,'area','넓이를 만드는 두 변 사이의 각이 둔각이라는 조건을 확인했나요?','넓이로부터 사인 값을 구하고 그 값에 대응하는 둔각을 선택하세요.',r'$10\sqrt2=\frac12\times8\times5\sin B$에서 $\sin B=\frac{\sqrt2}{2}$입니다.|$180^\circ-B$는 예각이고 사인 값이 같으므로 $180^\circ-B=45^\circ$, $B=135^\circ$입니다.','예각 해를 그대로 답으로 쓰지 않았나요?',(4,550,234,780,378))
add(2,r'$\angle B=15^\circ$, $\angle C=45^\circ$인 삼각형 $ABC$의 넓이가 $3-\sqrt3$이다. 둘레가 $p\sqrt2+q\sqrt3+r\sqrt6$일 때, 유리수 $p,q,r$에 대하여 $p+2q+3r$의 값은?',r'$4$|$6$|$8$|$10$|$12$',3,'area','둔각 꼭짓점 너머로 변을 연장해 수선을 내릴 수 있나요?','특수각 직각삼각형으로 세 변을 한 문자로 나타내고 넓이로 크기를 정하세요.',r'$B$에서 $CA$의 연장선에 내린 수선의 발을 $D$라 하고 $AD=t$라 하면 $AB=2t$, $BD=\sqrt3t$입니다.|$\triangle BDC$는 직각이등변삼각형이므로 $DC=\sqrt3t$, $BC=\sqrt6t$, $AC=(\sqrt3-1)t$입니다.|넓이는 $\frac12\cdot2t\cdot(\sqrt3-1)t\cdot\sin120^\circ=\frac{3-\sqrt3}{2}t^2$이므로 $t=\sqrt2$입니다.|세 변의 합은 $\sqrt2+2\sqrt3+\sqrt6$이므로 $p+2q+3r=1+4+3=8$입니다.','같은 제곱근 항끼리 모은 계수를 읽었나요?',(4,550,785,783,863))
add(2,r'볼록사각형 $ABCD$의 두 대각선 길이는 $a,b$이고 두 대각선이 이루는 각은 $60^\circ$이다. $a+b=12$일 때 넓이의 최댓값을 $S$라 하면 $S^2$의 값은?',r'$81$|$108$|$162$|$243$|$324$',4,'area','대각선으로 나눈 네 삼각형의 넓이를 더할 수 있나요?','대각선의 곱으로 넓이를 나타내고 합이 일정한 두 수의 곱을 완전제곱식으로 바꾸세요.',r'대각선으로 나눈 넓이의 합은 $\frac12ab\sin60^\circ=\frac{\sqrt3}{4}ab$입니다.|$b=12-a$에서 넓이는 $-\frac{\sqrt3}{4}(a-6)^2+9\sqrt3$이므로 최댓값은 $S=9\sqrt3$입니다.|$S^2=243$입니다.','문제가 최댓값 자체인지 그 제곱인지 확인했나요?')
add(2,r'$\angle BAC=30^\circ$, $AB=AC$인 이등변삼각형 $ABC$에서 $D$는 $AC$ 위의 점이다. $AD=4$, $\angle BDC=\angle DCB$이고 $BC=a$일 때, $a^2$의 값은?',r'$4$|$6$|$8$|$12$|$16$',3,'ratio','같은 밑각과 같은 두 각이 각각 어떤 길이를 같게 하나요?','점에서 반대편 변에 수선을 내려 특수각 직각삼각형을 만드세요.',r'$B=C=75^\circ$이고 $\angle BDC=75^\circ$이므로 $BD=BC$입니다.|$D$에서 $AB$에 내린 수선의 발을 $H$라 하면 $DH=4\sin30^\circ=2$입니다. $\angle HBD=45^\circ$이므로 $BH=DH=2$입니다.|$BC^2=BD^2=2^2+2^2=8$입니다.','구하는 제곱을 바로 피타고라스 정리로 얻을 수 있나요?',(5,145,670,303,908))
add(2,r'높이가 $20\,m$인 건물 옥상에서 굴뚝 꼭대기를 올려다본 각은 $45^\circ$, 밑바닥을 내려다본 각은 $30^\circ$이다. 두 밑바닥은 같은 수평면 위에 있을 때 굴뚝의 높이는?',r'$10(\sqrt3+2)\,m$|$20(\sqrt3-1)\,m$|$10(\sqrt3+1)\,m$|$20(\sqrt3+1)\,m$|$30(\sqrt3-1)\,m$',4,'ratio','수평선 위와 아래의 높이를 나누어 볼 수 있나요?','아래 직각삼각형으로 수평거리를 구한 뒤 위 직각삼각형의 높이를 더하세요.',r'수평거리를 $d$라 하면 $\tan30^\circ=\frac{20}{d}$이므로 $d=20\sqrt3$입니다.|올려다본 각이 $45^\circ$이므로 옥상보다 높은 부분도 $20\sqrt3$입니다.|굴뚝의 전체 높이는 $20+20\sqrt3=20(\sqrt3+1)\,m$입니다.','관찰 지점의 높이를 빠뜨리지 않았나요?',(5,567,224,763,388))
add(2,r'수평면과 $26^\circ$ 기울어진 비탈길에서 $C$의 높이는 $1100\,m$이다. $A$에서 $C$까지 분속 $120\,m$로 걸을 때 걸리는 시간은? (단, $\sin26^\circ=0.44$로 계산한다.)',r'$20$분 $10$초|$20$분 $20$초|$20$분 $30$초|$20$분 $40$초|$20$분 $50$초',5,'ratio','높이와 실제로 걸어야 하는 거리 중 어느 것이 빗변인가요?','사인으로 비탈길 길이를 구한 뒤 속력으로 나누고 남은 분을 초로 바꾸세요.',r'$AC=\frac{1100}{0.44}=2500\,m$입니다.|시간은 $\frac{2500}{120}=20+\frac56$분이며 $\frac56\times60=50$초입니다.|따라서 $20$분 $50$초입니다.','소수 부분을 초로 바꾸는 데 어떤 수를 곱하나요?',(6,108,284,344,454))
add(2,r'그림과 같이 반지름이 $1$인 사분원이 있다. 다음 중 옳지 않은 것은?',r'$\sin x=BC$|$\cos y=BC$|$\tan z=\frac1{DE}$|$x$의 값이 커지면 $\sin x$의 값도 커진다.|$x$의 값이 커지면 $\cos x$의 값도 커진다.',5,'ratio','세 각이 속한 직각삼각형의 빗변을 구분했나요?','단위원에서 세로와 가로 길이가 예각의 변화에 따라 어떻게 바뀌는지 살펴보세요.',r'$AC=AD=1$이므로 $\sin x=BC$, $\cos y=BC$, $\tan z=\frac{AD}{DE}=\frac1{DE}$입니다.|예각 $x$가 커지면 높이 $BC$는 커지고 가로 $AB$는 작아집니다. 따라서 사인은 증가하지만 코사인은 감소합니다.','길이의 변화 방향을 반대로 설명한 보기는 무엇인가요?',(6,582,204,747,383))
add(2,r'주어진 삼각비 표를 이용하여 직사각형 $ABCD$의 넓이를 구하시오. 두 대각선의 교점은 $O$, $OD=2$, $\angle DOC=54^\circ$이다.',r'$3.24$|$4.72$|$6.48$|$7.20$|$8.00$',3,'area','대각선 전체 길이와 교점에서 끝점까지 길이를 구분했나요?','같은 넓이의 삼각형들을 합하여 대각선과 끼인각으로 넓이를 계산하세요.',r'직사각형의 대각선은 같고 서로를 이등분하므로 $AC=BD=4$입니다.|넓이는 $\frac12AC\cdot BD\sin54^\circ=8\sin54^\circ$입니다.|표의 $\sin54^\circ=0.81$을 사용하면 $8\times0.81=6.48$입니다.','표의 근삿값을 사용한 결과는 얼마인가요?',(6,523,809,808,1037))
add(2,r'다음 식의 값을 구하시오. $\frac12\tan45^\circ-3\sqrt2\cos45^\circ+\frac{4\sqrt3}{3}\sin60^\circ+\sqrt3\cos30^\circ$',r'$-1$|$0$|$1$|$2$|$3$',3,'ratio','각 삼각비가 특수각의 어떤 값인지 확인했나요?','먼저 삼각비를 정확한 분수로 바꾸고 각 항을 정리한 뒤 더하세요.',r'각 항은 차례로 $\frac12$, $-3$, $2$, $\frac32$입니다.|따라서 $\frac12-3+2+\frac32=1$입니다.','제곱근끼리의 곱과 음수 부호를 올바르게 계산했나요?')
add(2,r'직각삼각형 $ABC$에서 $\angle C=90^\circ$, $D$는 $AC$ 위의 점이다. $\angle DBC=60^\circ$, $AD=BD=2$일 때, $\tan15^\circ$의 값은?',r'$\sqrt3$|$2$|$1-\sqrt3$|$1+\sqrt3$|$2-\sqrt3$',5,'ratio','같은 두 변에서 생기는 작은 각을 확인할 수 있나요?','아래 직각삼각형의 두 직각변을 구한 뒤 전체 높이를 사용하세요.',r'$BC=2\cos60^\circ=1$, $CD=2\sin60^\circ=\sqrt3$입니다.|$\angle BDA=150^\circ$이고 $AD=BD$이므로 $\angle BAD=15^\circ$입니다.|$\tan15^\circ=\frac{BC}{AC}=\frac1{2+\sqrt3}=2-\sqrt3$입니다.','분모를 유리화한 식은 어느 보기인가요?',(7,181,644,277,871))
add(2,r'직사각형 종이 $ABCD$를 $EF$를 접는 선으로 접었더니 $D$가 $B$에 겹쳐졌다. $ED=\frac{3\sqrt3}{2}$, $DC=\sqrt6$, $\angle BEF=x$일 때, $\sin x\cos x\tan x$의 값은?',r'$\frac13$|$\frac12$|$\frac23$|$\frac34$|$1$',3,'fold','접는 선 위의 점에서 대응점까지 거리가 같나요?','접힌 길이와 평행선의 각을 이용하여 접는 선의 길이와 직각삼각형을 구하세요.',r'접기와 평행선의 각에서 $BE=BF=ED=\frac{3\sqrt3}{2}$입니다. 접힌 점을 $C^{\prime}$라 하면 $BC^{\prime}=\sqrt6$입니다.|직각삼각형 $BC^{\prime}F$에서 $C^{\prime}F=CF=\frac{\sqrt3}{2}$입니다. $F$에서 $AD$에 내린 수선의 발을 $H$라 하면 $EH=\sqrt3$, $FH=\sqrt6$, $EF=3$입니다.|$x=\angle HEF$이므로 $\sin x=\frac{\sqrt6}{3}$. $\sin x\cos x\tan x=\sin^2x=\frac23$입니다.','곱을 사인의 제곱으로 정리할 수 있나요?',(7,570,255,762,455))
add(2,r'$\angle C=90^\circ$인 삼각형 $ABC$에서 $B,D,E,C$가 이 순서로 일직선 위에 있고 $BD=DE=EC=AC=1$이다. $\alpha=\angle ABC$, $\beta=\angle ADC$, $\sin(\alpha+\beta)=k$일 때 $k^2$의 값은?',r'$\frac14$|$\frac13$|$\frac12$|$\frac23$|$\frac34$',3,'ratio','같은 길이로 나뉜 밑변에서 닮은 삼각형을 찾을 수 있나요?','대응변의 비와 끼인각이 같은 두 삼각형을 찾아 두 각의 합을 특수각과 연결하세요.',r'$BE=2$, $AE=\sqrt2$, $DE=1$입니다. $BE:AE=AE:DE=\sqrt2:1$이고 $\angle BEA=\angle AED$이므로 $\triangle ABE\sim\triangle DAE$입니다.|따라서 $\angle DAE=\alpha$. $\triangle DAE$의 외각 $\angle AEC=\alpha+\beta$입니다.|$AC=EC$인 직각삼각형에서 $\angle AEC=45^\circ$이므로 $k^2=\sin^245^\circ=\frac12$입니다.','두 각의 합을 구한 뒤 사인을 제곱하면 얼마인가요?',(7,549,819,788,936))
add(2,r'그림의 직각삼각형 $ABC$에 대하여 항상 옳은 것은?',r'$\sin A=\cos A$|$\sin B=\cos B$|$\tan A=\tan B$|$\sin A=\tan B$|$\cos A=\sin B$',5,'ratio','두 예각의 합은 얼마인가요?','두 각에 대한 삼각비를 각각 변의 비로 나타내어 비교하세요.',r'$A+B=90^\circ$입니다. $\cos A=\frac{AC}{AB}$이고 $\sin B=\frac{AC}{AB}$이므로 항상 같습니다.|나머지 등식은 특별한 각에서만 성립하거나 변의 비가 서로 다릅니다.','공통 빗변과 같은 직각변을 사용하는 식은 무엇인가요?',(8,153,198,287,363))
add(2,r'$\angle BAC=90^\circ$인 삼각형 $ABC$에서 $AB=3$, $AC=4$, $AH\perp BC$이다. $\angle BAH=x$, $\angle CAH=y$일 때, $\sin x-\sin y$의 값은?',r'$-\frac25$|$-\frac15$|$0$|$\frac15$|$\frac25$',2,'ratio','작은 직각삼각형의 각과 큰 삼각형의 각이 어떻게 대응하나요?','닮음으로 각을 옮겨 큰 삼각형의 변을 이용하세요.',r'$BC=5$이며 여각 관계에서 $x=\angle C$, $y=\angle B$입니다.|$\sin x=\frac35$, $\sin y=\frac45$이므로 차는 $-\frac15$입니다.','빼는 순서에 따라 부호가 달라짐을 확인했나요?',(8,118,823,338,952))
add(2,r'$\tan x=2$일 때, $\frac{2\sin x-3\cos x}{4\cos x+3\sin x}$의 값은?',r'$-\frac1{10}$|$\frac1{10}$|$\frac15$|$\frac12$|$1$',2,'ratio','분자와 분모를 같은 삼각비로 나눌 수 있나요?',r'$\tan x=\frac{\sin x}{\cos x}$가 되도록 식을 정리하세요.',r'탄젠트가 정의되므로 $\cos x\ne0$입니다. 분자와 분모를 $\cos x$로 나누면 $\frac{2\tan x-3}{4+3\tan x}$입니다.|$\tan x=2$를 넣으면 $\frac{4-3}{4+6}=\frac1{10}$입니다.','삼각비를 따로 구하지 않고 계산하면 얼마인가요?')
add(2,r'한 모서리 길이가 $a$인 정육면체에서 $M$은 $FG$의 중점이다. $\angle GAM=x$일 때, $\cos x$의 값은?',r'$\frac{\sqrt3}{9}$|$\frac{2\sqrt3}{9}$|$\frac{4\sqrt3}{9}$|$\frac{5\sqrt3}{9}$|$\frac{7\sqrt3}{9}$',4,'ratio','공간의 두 선분이 이루는 각을 하나의 평면 삼각형에서 볼 수 있나요?','세 변을 피타고라스 정리로 구한 뒤 수선을 내려 두 직각삼각형의 식을 빼세요.',r'$AG=\sqrt3a$, $AF=\sqrt2a$, $AM=\sqrt{2a^2+\frac{a^2}{4}}=\frac{3a}{2}$, $GM=\frac a2$입니다.|$M$에서 $AG$에 내린 수선의 발을 $P$, $AP=t$라 하면 $AM^2-t^2=GM^2-(AG-t)^2$입니다. 정리하면 $t=\frac{5a}{2\sqrt3}$입니다.|$\cos x=\frac{AP}{AM}=\frac{5\sqrt3}{9}$입니다.','모서리 길이가 약분된 삼각비는 얼마인가요?',(8,575,585,754,774))
C['power']=C['circle']+r' 두 현이 원 안에서 점 $P$에서 만나면 $PA\cdot PB=PC\cdot PD$입니다. 원 밖에서 두 할선을 그으면 가까운 교점까지의 길이와 먼 교점까지의 길이의 곱이 같습니다. 접선이면 접선 길이의 제곱과 같습니다. 이 관계는 원주각이 같은 두 삼각형의 $AA$ 닮음으로 대응변의 비를 세워 얻습니다. 곱에 넣는 선분은 반드시 같은 출발점에서 재어야 합니다.'
add(3,r'그림의 직각삼각형 $ABC$에서 삼각비의 값으로 옳은 것은?',r'$\sin B=\frac57$|$\cos A=\frac{2\sqrt6}{3}$|$\cos A=\frac{2\sqrt6}{5}$|$\sin C=\frac{2\sqrt6}{5}$|$\cos C=\frac57$',1,'ratio','직각의 위치와 주어진 빗변을 먼저 찾았나요?','각 보기의 기준각에 맞는 변의 비를 구하세요.',r'$AB=7$, $AC=5$, $BC=\sqrt{49-25}=2\sqrt6$입니다.|$\sin B=\frac{AC}{AB}=\frac57$이고 $\cos A=\frac57$, $\sin C=1$, $\cos C=0$입니다.','정의와 일치하는 보기는 무엇인가요?',(1,172,378,339,568))
add(3,r'$(\sin60^\circ+\cos60^\circ)(\sin30^\circ-\cos30^\circ)$를 계산하면?',r'$0$|$\frac12$|$1$|$-\frac12$|$-\frac52$',4,'ratio','서로 여각인 특수각의 사인과 코사인 값을 확인했나요?','대입 후 합과 차의 곱을 제곱의 차로 정리하세요.',r'주어진 식은 $\frac{\sqrt3+1}{2}\cdot\frac{1-\sqrt3}{2}$입니다.|분자는 $(1+\sqrt3)(1-\sqrt3)=1-3=-2$이므로 값은 $-\frac12$입니다.','곱의 부호까지 확인하면 어느 보기인가요?')
add(3,r'보기에서 옳은 것만 있는 대로 고른 것은?'+ '\n'+r'ㄱ. $\sin90^\circ=0$  ㄴ. $\cos0^\circ=0$  ㄷ. $\sin60^\circ=\frac{\sqrt3}{2}$  ㄹ. $\cos30^\circ=\frac{\sqrt2}{2}$  ㅁ. $\tan45^\circ=1$  ㅂ. $\sin0^\circ+\tan0^\circ=0$',r'ㄱ, ㄴ|ㄴ, ㄷ|ㄱ, ㅁ, ㅂ|ㄷ, ㄹ, ㅂ|ㄷ, ㅁ, ㅂ',5,'ratio','끝각과 특수각의 값을 서로 바꾸어 외우지는 않았나요?','단위원의 가로·세로 길이와 특수각 삼각형을 이용해 각각 판단하세요.',r'$\sin90^\circ=1$, $\cos0^\circ=1$이므로 ㄱ, ㄴ은 거짓입니다.|ㄷ과 ㅁ은 참이고 $\cos30^\circ=\frac{\sqrt3}{2}$이므로 ㄹ은 거짓입니다.|$\sin0^\circ=\tan0^\circ=0$이므로 ㅂ도 참입니다.','참인 항목을 빠짐없이 모으면 어느 조합인가요?')
add(3,r'직각삼각형 $ABC$에서 $AC=10$, $\angle A=29^\circ$이다. 아래 삼각비 표를 이용한 $x=BC$의 값은?',r'$0.04848$|$0.4848$|$4.848$|$0.04695$|$0.04540$',3,'ratio','주어진 변은 빗변인가요, 기준각의 맞은편 변인가요?','표에서 기준각의 사인을 읽어 빗변과 곱하세요.',r'$\sin29^\circ=\frac{x}{10}$입니다.|표에서 $\sin29^\circ=0.4848$이므로 $x=10\times0.4848=4.848$입니다.','소수점의 위치를 확인했나요?',(1,458,608,806,848))
add(3,r'$\triangle ABC$에서 $\angle B=30^\circ$, $\angle C=45^\circ$, $BC=8$이다. 삼각형의 넓이는?',r'$4(\sqrt2-1)$|$16(\sqrt3-1)$|$8(\sqrt2-1)$|$2(\sqrt2+1)$|$2(\sqrt3+1)$',2,'area','높이를 내린 뒤 두 밑변 부분을 같은 높이로 나타낼 수 있나요?','두 부분의 합으로 높이를 구하고 넓이 공식에 넣으세요.',r'높이를 $h$라 하면 밑변의 두 부분은 $\sqrt3h$, $h$입니다.|$(\sqrt3+1)h=8$이므로 $h=4(\sqrt3-1)$입니다.|넓이는 $\frac12\times8\times h=16(\sqrt3-1)$입니다.','마지막 넓이의 곱을 계산하면 얼마인가요?',(2,132,199,368,325))
add(3,r'두 직각삼각형 $ABC,DBC$에서 $\angle A=\angle BCD=90^\circ$, $\angle ACB=45^\circ$, $\angle BDC=60^\circ$, $AB=3\sqrt2$이다. $BC=x$, $CD=y$일 때, $xy$의 값은?',r'$12\sqrt3$|$36\sqrt3$|$9\sqrt3$|$12\sqrt2$|$36\sqrt2$',1,'ratio','공통 변을 첫 직각삼각형에서 구할 수 있나요?','특수각 변의 비를 각 삼각형에 차례로 적용하세요.',r'$\triangle ABC$는 직각이등변삼각형이므로 $BC=3\sqrt2\times\sqrt2=6$입니다.|$\tan60^\circ=\frac{BC}{CD}$이므로 $CD=\frac6{\sqrt3}=2\sqrt3$입니다.|$xy=6\times2\sqrt3=12\sqrt3$입니다.','길이의 합이 아닌 곱을 구했나요?',(2,119,632,378,795))
add(3,r'똑바로 서 있던 나무가 부러져 그림처럼 꼭대기가 땅에 닿았다. $BC=15\,m$, $\angle ACB=60^\circ$일 때, 원래 나무의 높이는?',r'$30\,m$|$(30+15\sqrt3)\,m$|$15\sqrt3\,m$|$5\sqrt3\,m$|$(30+5\sqrt3)\,m$',2,'ratio','남아 있는 수직 부분과 부러진 부분을 모두 더해야 하나요?','하나의 직각삼각형에서 밑변을 기준으로 높이와 빗변을 각각 구하세요.',r'$AB=15\tan60^\circ=15\sqrt3\,m$입니다.|$AC=\frac{15}{\cos60^\circ}=30\,m$입니다.|원래 길이는 $AB+AC=30+15\sqrt3\,m$입니다.','나무가 차지했던 두 부분을 모두 포함했나요?',(2,552,222,741,407))
add(3,r'한 모서리 길이가 $2$인 정육면체에서 $\angle DFH=x^\circ$일 때, $\sin x^\circ\cos x^\circ$의 값은?',r'$\frac{\sqrt3}{2}$|$\frac{\sqrt6}{3}$|$\frac{\sqrt2}{6}$|$\frac{2\sqrt2}{3}$|$\frac{\sqrt2}{3}$',5,'ratio','공간대각선과 밑면대각선이 이루는 직각삼각형을 찾았나요?','두 번의 피타고라스 정리로 세 변을 구하세요.',r'$DH=2$, $FH=2\sqrt2$, $DF=2\sqrt3$입니다.|$\sin x^\circ=\frac1{\sqrt3}$, $\cos x^\circ=\frac{\sqrt2}{\sqrt3}$이므로 곱은 $\frac{\sqrt2}{3}$입니다.','기준각의 높이와 밑변을 맞게 사용했나요?',(2,541,622,747,806))
add(3,r'한 변이 $6$인 정사각형 $ABCD$를 $B$를 중심으로 $30^\circ$ 회전시켜 정사각형 $A^{\prime}BC^{\prime}D^{\prime}$을 만들었다. $AD$와 $C^{\prime}D^{\prime}$의 교점을 $E$라 할 때, $AE$의 길이는?',r'$2\sqrt3$|$2\sqrt2$|$3$|$3\sqrt2$|$3\sqrt3$',1,'ratio','회전 후에도 같은 변의 길이와 직각이 보존되나요?','회전된 꼭짓점의 수평·수직 위치를 삼각비로 구한 뒤 교점까지 이동량을 계산하세요.',r'$B$를 원점, $BC$를 가로축으로 놓으면 $C^{\prime}=(6\cos30^\circ,6\sin30^\circ)=(3\sqrt3,3)$입니다.|$AD$는 높이 $6$인 수평선입니다. $C^{\prime}D^{\prime}$을 따라 위로 $3$ 올라갈 때 왼쪽으로 $\frac3{\sqrt3}=\sqrt3$ 이동합니다.|$E$의 가로좌표는 $2\sqrt3$이고 $A$의 가로좌표는 $0$이므로 $AE=2\sqrt3$입니다.','교점과 원래 꼭짓점 사이의 수평거리는 얼마인가요?',(3,142,244,349,442))
add(3,r'$\angle C=90^\circ$, $AC=12$인 삼각형 $ABC$에서 $D$는 $BC$ 위의 점이고 $AD=BD$이다. $\angle ABC=x$, $\angle ADC=y$, $\tan x=\frac23$일 때, $\cos y$의 값은?',r'$\frac23$|$\frac12$|$\frac{\sqrt3}{2}$|$\frac5{13}$|$\frac{12}{13}$',4,'ratio','같은 길이를 한 문자로 놓으면 전체 밑변을 나눌 수 있나요?','큰 삼각형에서 밑변을 구하고 작은 직각삼각형의 피타고라스 식을 세우세요.',r'$BC=\frac{12}{2/3}=18$입니다. $AD=BD=t$라 하면 $DC=18-t$입니다.|$t^2=12^2+(18-t)^2$에서 $t=13$, $DC=5$입니다.|$\cos y=\frac{DC}{AD}=\frac5{13}$입니다.','작은 삼각형의 빗변을 분모에 넣었나요?',(3,149,744,347,864))
add(3,r'그림의 원 $O$에서 중심에서 현에 내린 수선이 현과 만나는 점까지 현의 한쪽 길이가 $5$이다. 현 전체 길이 $x$의 값은?',r'$6$|$7$|$8$|$9$|$10$',5,'chord','수선의 발은 현의 어느 점인가요?','현의 양쪽 부분이 같다는 성질을 적용하세요.',r'원의 중심에서 현에 내린 수선은 현을 이등분합니다.|따라서 $x=5+5=10$입니다.','표시된 길이가 절반이라는 점을 반영했나요?',(3,572,175,725,329))
add(3,r'그림의 원 $O$에서 반지름이 $13$이고 위아래 두 현의 길이는 모두 $10$이다. 중심에서 위쪽 현까지의 거리 $x$는?',r'$12$|$\sqrt{69}$|$24$|$10$|$12\sqrt3$',1,'chord','현의 길이를 반으로 나눈 값은 얼마인가요?','반지름을 빗변으로 하는 직각삼각형의 나머지 변을 구하세요.',r'현의 절반은 $5$입니다.|$x^2+5^2=13^2$에서 $x^2=144$, 거리이므로 $x=12$입니다.','양의 제곱근을 선택했나요?',(3,568,650,726,809))
add(3,r'그림의 원 $O$에서 $\angle APB=25^\circ$, $\angle DQC=75^\circ$, 작은 호 $AB$의 길이가 $3$일 때, 작은 호 $DC$의 길이 $x$는?',r'$7$|$8$|$9$|$10$|$11$',3,'circle','같은 원에서 호의 길이비와 원주각의 비는 어떤 관계인가요?','중심각이 원주각의 두 배인 점을 이용해 비례식을 세우세요.',r'호의 길이는 중심각에 비례하며 같은 원에서는 원주각에도 비례합니다.|$x:3=75:25=3:1$이므로 $x=9$입니다.','호의 길이에 적용할 배율은 얼마인가요?',(4,165,176,336,353))
add(3,r'그림의 원 $O$에서 작은 중심각 $\angle AOB=120^\circ$이고 $P$는 작은 호 $AB$ 위에 있다. $x=\angle APB$의 크기는?',r'$80^\circ$|$90^\circ$|$100^\circ$|$110^\circ$|$120^\circ$',5,'circle','각의 꼭짓점을 포함하지 않는 호는 큰 호인가요 작은 호인가요?','원주각이 보는 호의 중심각을 한 바퀴에서 빼서 구하세요.',r'$\angle APB$가 보는 큰 호 $AB$의 중심각은 $360^\circ-120^\circ=240^\circ$입니다.|따라서 $x=\frac{240^\circ}{2}=120^\circ$입니다.','작은 중심각을 바로 절반으로 나누지 않았나요?',(4,173,625,335,793))
add(3,r'그림에서 $A,B$는 원 $O$의 접점이다. $PA=9$이고 선분 $PO$가 원과 처음 만나는 점을 $Q$라 할 때 $PQ=3$이다. 반지름 $x=OB$의 값은?',r'$10$|$11$|$12$|$13$|$14$',3,'tangent','같은 외부 점에서 그은 두 접선의 길이는 같나요?','중심까지의 거리를 반지름과 바깥 부분의 합으로 나타내세요.',r'$PB=PA=9$이고 $PO=x+3$입니다. 접점에서 반지름은 접선에 수직입니다.|$(x+3)^2=x^2+9^2$에서 $6x=72$, $x=12$입니다.','삼각형의 빗변은 어느 선분인지 확인했나요?',(4,563,202,742,366))
add(3,r'사각형 $ABCD$는 원 $O$에 외접한다. $AD=3$, $BC=7$이고 원의 넓이가 $4\pi$일 때, 사각형의 넓이는?',r'$16$|$18$|$20$|$22$|$24$',3,'tangent','원에서 각 변까지의 거리는 모두 얼마인가요?','중심과 꼭짓점을 이은 삼각형들의 넓이를 반둘레와 반지름으로 합하세요.',r'$\pi r^2=4\pi$에서 $r=2$입니다. 외접사각형에서 $AB+CD=AD+BC=10$이므로 반둘레는 $10$입니다.|네 삼각형의 높이가 모두 $2$이므로 넓이는 $rs=2\times10=20$입니다.','주어진 두 대변의 합이 반둘레인 이유를 설명할 수 있나요?',(4,516,681,778,885))
add(3,r'원 $O$에서 $AB$는 지름이고 $\angle ACD=62^\circ$이다. $x=\angle BAD$의 크기는?',r'$26^\circ$|$28^\circ$|$31^\circ$|$45^\circ$|$62^\circ$',2,'circle','같은 현을 보는 두 원주각을 찾았나요?','원주각을 다른 삼각형으로 옮긴 뒤 지름의 직각을 이용하세요.',r'$\angle ABD=\angle ACD=62^\circ$이고 지름에 대한 각 $\angle ADB=90^\circ$입니다.|$x=180^\circ-90^\circ-62^\circ=28^\circ$입니다.','나머지 예각의 크기는 얼마인가요?',(5,158,177,341,342))
add(3,r'보기의 사각형 $ABCD$ 중 원에 내접하는 것만 있는 대로 고른 것은?',r'ㄱ|ㄷ|ㄱ, ㄴ|ㄴ, ㄹ|ㄷ, ㄹ',2,'power','각의 조건과 교차 선분의 길이 조건을 각각 확인했나요?','같은 현의 원주각, 대각의 합, 할선 또는 현의 곱으로 내접 여부를 검토하세요.',r'ㄱ은 같은 현 $BC$에 대한 각이 $90^\circ,80^\circ$로 달라 내접하지 않습니다. ㄴ은 대각의 합이 $75^\circ+70^\circ=145^\circ$로 내접하지 않습니다.|ㄷ은 $PD\cdot PA=5\times9=45$, $PC\cdot PB=3\times15=45$로 같아 두 할선의 곱 관계의 역에 의해 내접합니다.|ㄹ은 두 대각선 조각의 곱이 $3\times5=15$, $4\times4=16$으로 달라 내접하지 않습니다.','모든 판정 조건을 통과한 그림은 무엇인가요?',(5,64,558,431,811))
add(3,r'$AB$는 원 $O$의 지름이고 $PT$는 접선이다. $P,A,O,B$가 한 직선 위에 있고 $PA=1$, $PT=\sqrt3$일 때, 작은 호 $AT$의 길이는?',r'$\frac{\sqrt2}{3}\pi$|$\frac13\pi$|$\frac{\sqrt2}{2}\pi$|$\sqrt3\pi$|$\frac{\sqrt3}{2}\pi$',2,'tangent','반지름과 바깥 부분을 합하면 중심까지의 거리가 되나요?','접점의 직각에서 반지름을 구한 뒤 특수각을 찾아 호의 길이를 구하세요.',r'반지름을 $r$라 하면 $OP=r+1$, $OT=r$이고 $(r+1)^2=r^2+3$에서 $r=1$입니다.|$OP=2$, $OT=1$이므로 $\angle POT=60^\circ$입니다. 이는 $\angle AOT$와 같습니다.|호의 길이는 $2\pi\times1\times\frac{60}{360}=\frac\pi3$입니다.','원의 둘레 중 해당 중심각이 차지하는 비율은 얼마인가요?',(5,558,197,741,367))
add(3,r'오각형 $ABCDE$가 원 $O$에 내접하고 $\angle BOC=80^\circ$일 때, $\angle A+\angle D$의 크기는?',r'$130^\circ$|$170^\circ$|$200^\circ$|$220^\circ$|$260^\circ$',4,'circle','두 원주각이 보는 호를 합하면 어떤 호가 중복되나요?','두 호의 중심각 합을 한 바퀴와 공통 호의 합으로 나타내세요.',r'$\angle A$가 보는 호 $BCDE$와 $\angle D$가 보는 호 $CBAE$의 합은 원 한 바퀴와 호 $BC$를 더한 것과 같습니다.|따라서 $\angle A+\angle D=\frac{360^\circ+80^\circ}{2}=220^\circ$입니다.','중복되는 호까지 포함한 다음 절반으로 나누었나요?',(5,567,636,730,796))
add(3,r'원 밖의 점 $P$를 지나는 두 직선이 원과 만나는 점을 그림처럼 $A,B,C,D$라 한다. $\angle AOD=100^\circ$, $\angle COB=38^\circ$일 때, $\angle P$의 크기는?',r'$28^\circ$|$29^\circ$|$30^\circ$|$31^\circ$|$32^\circ$',4,'circle','바깥 각이 보는 먼 호와 가까운 호를 구분했나요?','원주각과 삼각형의 외각을 이용해 두 중심각의 차를 절반으로 나누세요.',r'두 할선의 바깥 각은 먼 호와 가까운 호의 중심각 차의 절반입니다.|$\angle P=\frac{100^\circ-38^\circ}{2}=31^\circ$입니다.','두 각의 합이 아닌 차를 사용했나요?',(6,111,222,380,370))
add(3,r'그림의 원에서 교차하는 두 현의 한쪽 조각은 각각 $5x$, $2x-1$이고 다른 현의 조각은 $x$, $7x+1$이다. $x$의 값은?',r'$2$|$3$|$4$|$5$|$6$',1,'power','같은 현에 놓인 두 조각을 올바르게 짝지었나요?','교점에서 나뉜 두 현의 곱을 같게 놓되 길이의 양수 조건도 확인하세요.',r'$5x(2x-1)=x(7x+1)$입니다.|$3x^2-6x=3x(x-2)=0$이고 선분의 길이가 양수이므로 $x=0$은 제외됩니다.|따라서 $x=2$입니다.','방정식의 해가 모두 실제 길이가 될 수 있나요?',(6,172,676,330,826))
add(3,r'직선 $AT$가 원의 접선이고 $\angle BAT$가 예각일 때, $\angle BAT=\angle BPA$를 증명하는 과정이다. 그림의 빈칸에 들어갈 내용으로 옳지 않은 것은?',r'$90^\circ$|$\angle CPB$|원주각|$\angle BAT$|$\angle ABP$',5,'circle','직각에서 빼는 두 각이 어느 꼭짓점의 각인지 확인했나요?','지름의 원주각과 같은 호의 원주각을 이용하여 두 각을 같은 각의 여각으로 표현하세요.',r'지름 $AC$와 접선은 수직이며 $\angle CPA=90^\circ$입니다. 따라서 첫 빈칸은 직각입니다.|$\angle CAB=\angle CPB$는 호 $BC$에 대한 같은 원주각입니다.|$\angle BAT=90^\circ-\angle CAB$, $\angle BPA=90^\circ-\angle CPB$이므로 마지막 빈칸은 $\angle BPA$여야 합니다. 보기 $5$는 틀립니다.','마지막 각의 가운데 글자가 어느 꼭짓점을 나타내야 하나요?',(6,457,213,826,628))
add(3,r'원 $O$의 두 현 $AB,CD$가 점 $P$에서 서로 직교한다. $PA=12$, $PB=4$, $PC=x$, $PD=y$이고 반지름이 $10$일 때, $y-x$의 값은? (단, $x<y$)',r'$9$|$10$|$11$|$12$|$13$',4,'chord','두 현의 중점과 중심 사이에 직사각형을 만들 수 있나요?','한 현의 반길이로 중심과 현의 거리를 구하고 다른 현의 두 조각 차와 연결하세요.',r'$AB=16$이므로 중심에서 $AB$까지의 거리는 $\sqrt{10^2-8^2}=6$입니다.|$CD\perp AB$이고 $P$는 $AB$ 위에 있으므로 $CD$의 중점과 $P$ 사이 거리가 바로 $6$입니다.|따라서 $\frac{y-x}{2}=6$, $y-x=12$입니다.','중점까지의 거리는 두 조각 차의 얼마인가요?',(7,171,224,334,382))
add(3,r'$\triangle ABC$는 원에 내접하고 $AQ$는 $\angle BAC$의 이등분선이다. $P=AQ\cap BC$, $AB=5$, $AC=4$, $PQ=1$일 때 $AP$의 길이는?',r'$\frac12$|$1$|$\frac32$|$3$|$4$',5,'power','각의 이등분과 원주각으로 닮은 삼각형을 찾을 수 있나요?','한 쌍의 공통각과 같은 호의 각으로 비례식을 세워 두 알려진 변의 곱을 만드세요.',r'$\angle BAP=\angle CAQ$이고 $\angle ABP=\angle AQC$이므로 $\triangle ABP\sim\triangle AQC$입니다.|따라서 $AB: AQ=AP:AC$이므로 $AP\cdot AQ=AB\cdot AC=20$입니다.|$AP=t$, $AQ=t+1$에서 $t(t+1)=20$, $(t-4)(t+5)=0$입니다. 길이는 양수이므로 $AP=4$입니다.','전체 선분과 부분 선분을 구분하여 해를 골랐나요?',(7,171,718,331,884))
add(3,r'$PA,PB$는 원 $O$의 접선이고 $A,B$는 접점이다. $\angle APB=40^\circ$, 호 $AC:BC=2:3$일 때, $\angle BAC$의 크기는?',r'$22^\circ$|$33^\circ$|$44^\circ$|$55^\circ$|$66^\circ$',5,'circle','접점의 직각으로 작은 중심각을 구할 수 있나요?','큰 호를 주어진 비로 나누고 원하는 원주각이 보는 호를 선택하세요.',r'사각형 $OAPB$에서 $\angle AOB=360^\circ-90^\circ-90^\circ-40^\circ=140^\circ$입니다.|$C$를 지나는 큰 호 $AB$의 중심각은 $220^\circ$입니다. 이 중 호 $BC$는 $\frac35$이므로 중심각은 $132^\circ$입니다.|$\angle BAC=\frac{132^\circ}{2}=66^\circ$입니다.','호의 비를 적용한 다음 원주각으로 바꾸었나요?',(7,498,229,795,415))
add(4,r'$y=-x^2+7x$의 그래프에서 $y$좌표가 같은 서로 다른 두 점 $A,D$를 잡고, 각 점에서 $x$축에 내린 수선의 발을 $B,C$라 한다. 그림처럼 $A,D$가 $x$축 위쪽에 있을 때 직사각형 $ABCD$의 둘레의 최댓값은?',r'$\frac{49}{2}$|$25$|$\frac{51}{2}$|$26$|$\frac{53}{2}$',5,'quad','대칭축을 기준으로 두 점의 가로좌표를 한 문자로 나타낼 수 있나요?','가로와 세로를 한 문자로 나타낸 둘레 식을 완전제곱식으로 고치세요.',r'$B$의 가로좌표를 $t$라 하면 $C$의 가로좌표는 $7-t$입니다. $0<t<\frac72$이며 가로는 $7-2t$, 높이는 $-t^2+7t$입니다.|둘레는 $2(-t^2+5t+7)=-2(t-\frac52)^2+\frac{53}{2}$입니다.|$t=\frac52$는 가능한 범위에 있으므로 최댓값은 $\frac{53}{2}$입니다.','최댓값이 실제로 가능한 위치에서 나오는지 확인했나요?',(1,117,412,303,586))
add(4,r'축구공을 찬 뒤 $t$초 후의 높이 $y\,m$가 $y=-4.9t^2+19.6t$이다. 최고점에 도달하는 시간을 $a$초, 최고 높이를 $b\,m$, 다시 땅에 도달하는 시간을 $c$초라 할 때, 수치 $a+b+c$의 값은?',r'$24.6$|$25.1$|$25.6$|$26.1$|$26.6$',3,'quad','꼭짓점과 두 근이 각각 어떤 시간을 의미하나요?','완전제곱식으로 최고점을 찾고 함수값이 영인 양의 시간을 구하세요.',r'$y=-4.9(t-2)^2+19.6$이므로 $a=2$, $b=19.6$입니다.|$-4.9t(t-4)=0$에서 다시 땅에 닿는 양의 시간은 $c=4$입니다.|수치의 합은 $2+19.6+4=25.6$입니다.','처음 출발하는 시각을 착지 시각으로 선택하지 않았나요?',reason='서로 다른 단위의 수치를 더하는 문제이므로 수치의 합임을 명시하고 원본 보기의 부적절한 m 단위를 제거.')
add(4,r'이차함수 $y=x^2-2kx+5$의 최솟값이 양수가 되게 하는 자연수 $k$들의 합은?',r'$0$|$1$|$2$|$3$|$5$',4,'quad','최솟값을 상수에 관한 식으로 나타낼 수 있나요?','완전제곱식의 남은 상수항이 양수가 되도록 부등식을 세우세요.',r'$y=(x-k)^2+5-k^2$이므로 최솟값은 $5-k^2$입니다.|$k^2<5$를 만족하는 자연수는 $1,2$입니다. 합은 $3$입니다.','경계값을 포함하는지와 자연수 조건을 확인했나요?')
add(4,r'$y=a(x+p)^2-q$가 $x=-3$에서 최솟값 $-4$를 가질 때, $a$의 부호와 $p,q$의 값은?',r'$a>0,p=3,q=-4$|$a>0,p=-3,q=4$|$a>0,p=3,q=4$|$a<0,p=-3,q=4$|$a<0,p=3,q=-4$',3,'quad','식에 쓰인 부호와 꼭짓점 좌표의 부호를 구분했나요?','최솟값을 갖는 방향을 먼저 정한 뒤 꼭짓점 좌표를 비교하세요.',r'최솟값이 있으므로 $a>0$입니다.|꼭짓점은 $(-p,-q)=(-3,-4)$이므로 $p=3$, $q=4$입니다.','세 조건이 모두 일치하는 보기는 무엇인가요?')
add(4,r'각 $A$가 공통인 세 직각삼각형 $ABC$, $AB^{\prime}C^{\prime}$, $AB^{\prime\prime}C^{\prime\prime}$에서 $AB=4$, $AB^{\prime}=8$, $AB^{\prime\prime}=12$, $\tan A=\frac34$이다. $CC^{\prime\prime}$의 길이는?',r'$8$|$9$|$10$|$11$|$12$',3,'ratio','닮은 세 삼각형의 빗변이 같은 직선 위에 있나요?','각 삼각형의 변을 같은 비로 구한 뒤 가장 큰 빗변에서 작은 빗변을 빼세요.',r'첫 삼각형에서 $BC=3$이므로 $AC=5$입니다.|가장 큰 삼각형의 배율은 $12:4=3:1$이므로 $AC^{\prime\prime}=15$입니다.|$CC^{\prime\prime}=15-5=10$입니다.','전체 길이와 남은 구간 길이를 구분했나요?',(1,494,775,678,953))
add(4,r'반지름이 $1$인 사분원과 직각삼각형 $AOB,COD$가 그림과 같다. $OB=0.6428$일 때, 표를 이용한 $AB+CD$의 값은?',r'$1.9578$|$1.8346$|$1.6051$|$1.4819$|$2.0309$',1,'ratio','단위원에서 가로 길이는 각의 어떤 삼각비인가요?','표의 코사인에서 각을 찾고 사인과 탄젠트를 각각 세로 길이에 연결하세요.',r'$OA=OD=1$이고 $\cos\angle AOB=0.6428$이므로 표에서 $\angle AOB=50^\circ$입니다.|$AB=\sin50^\circ=0.7660$, $CD=\tan50^\circ=1.1918$입니다.|합은 $0.7660+1.1918=1.9578$입니다.','단위원 안의 높이와 바깥 접선 위 높이를 구분했나요?',(2,57,211,416,342),reason='원본 그림의 OB=0.5736은 본문 OB=0.6428과 모순. 본문·표·정답에 맞춰 단위원 그림을 새로 작성.')
add(4,r'예각 $A$의 삼각비에 대한 설명 중 옳은 것을 모두 고른 것은?'+ '\n'+r'ㄱ. $A=45^\circ$일 때 $\sin^2A=\cos^2A$  ㄴ. $45^\circ<A<90^\circ$일 때 $\tan A<1$  ㄷ. $0^\circ<A<45^\circ$일 때 $\sin A>\cos A$  ㄹ. $0^\circ<A\le45^\circ$일 때 $0<\tan A\le1$  ㅁ. $45^\circ<A<90^\circ$일 때 $\cos A<\sin A$',r'ㄱ, ㄹ|ㄱ, ㅁ|ㄱ, ㄹ, ㅁ|ㄴ, ㄹ, ㅁ|ㄷ, ㄹ, ㅁ',3,'ratio','예각이 커질 때 가로와 세로 길이는 어떻게 바뀌나요?','중간 특수각을 기준으로 사인과 코사인, 탄젠트의 크기를 비교하세요.',r'$45^\circ$에서는 사인과 코사인이 같으므로 ㄱ은 참입니다.|$45^\circ$보다 큰 예각에서는 사인이 코사인보다 크고 탄젠트가 $1$보다 큽니다. 따라서 ㄴ은 거짓, ㅁ은 참입니다.|$45^\circ$보다 작은 예각에서는 사인이 코사인보다 작아 ㄷ은 거짓입니다. 해당 구간의 탄젠트는 양수이고 $1$ 이하이므로 ㄹ은 참입니다.','참인 항목이 모두 포함된 조합은 무엇인가요?',reason='원본 ㄱ의 sin A² 표기가 모호하고 참인 ㄱ,ㄹ,ㅁ 조합이 보기에 없음. 제곱 표기를 sin² A로 명확히 하고 ③을 ㄱ,ㄹ,ㅁ으로 수정.')
add(4,r'건물에 그림처럼 사다리를 걸쳐 놓았다. $BC=5\,m$, $\angle ABC=53^\circ$일 때, 사다리 길이 $AB$는?',r'$5\sin53^\circ\,m$|$5\cos53^\circ\,m$|$5\tan53^\circ\,m$|$\frac5{\sin53^\circ}\,m$|$\frac5{\cos53^\circ}\,m$',5,'ratio','사다리와 땅 위의 거리가 각각 어떤 변인가요?','코사인의 정의를 사용해 빗변을 미지수로 놓은 식을 풀어 보세요.',r'$\cos53^\circ=\frac{BC}{AB}=\frac5{AB}$입니다.|따라서 $AB=\frac5{\cos53^\circ}\,m$입니다.','빗변이 주어진 직각변보다 길어지는 식인가요?',(2,499,211,638,374))
add(4,r'수평 지면에서 $30\,m$ 떨어진 두 지점 $A,B$에서 같은 반딧불이 $C$를 올려다본 각이 각각 $30^\circ,45^\circ$였다. 그림처럼 $B$가 더 가까울 때, 반딧불이의 높이는?',r'$15\,m$|$15\sqrt3\,m$|$30\sqrt3\,m$|$15(1+\sqrt3)\,m$|$30(1+\sqrt3)\,m$',4,'ratio','공통 높이에 대해 두 수평거리를 나타낼 수 있나요?','두 직각삼각형의 수평거리 차가 관찰 지점 사이 거리임을 사용하세요.',r'높이를 $h$라 하면 가까운 수평거리는 $h$, 먼 수평거리는 $\sqrt3h$입니다.|$\sqrt3h-h=30$에서 $h=\frac{30}{\sqrt3-1}=15(\sqrt3+1)\,m$입니다.','지점 사이 거리를 전체 수평거리로 오해하지 않았나요?',(2,494,799,696,931))
add(4,r'원 위의 네 점 $A,B,C,D$에 대하여 $AC\perp BD$이다. 교점을 $P$라 할 때 $AP=4\,cm$, $BP=DP=6\,cm$이다. 원의 반지름은?',r'$6\,cm$|$6.5\,cm$|$7\,cm$|$7.5\,cm$|$8\,cm$',2,'power','한 현을 수직이등분하는 직선은 원의 어디를 지나나요?','현의 곱으로 나머지 조각을 구한 뒤 지름 전체를 구하세요.',r'$BP=DP$이고 $AC\perp BD$이므로 $AC$는 현 $BD$의 수직이등분선이며 중심을 지나는 지름입니다.|$AP\cdot PC=BP\cdot PD=36$에서 $PC=9\,cm$입니다.|지름 $AC=13\,cm$이므로 반지름은 $6.5\,cm$입니다.','전체 지름을 구한 뒤 절반으로 나누었나요?',(3,99,183,255,349))
add(4,r'원의 중심에서 같은 거리에 있는 두 현의 길이가 같음을 증명하는 과정이다. 그림의 빈칸에 들어갈 것으로 옳지 않은 것은?',r'$\angle ONC$|$OC$|$ON$|$\triangle OCN$|$SAS$',5,'chord','주어진 같은 두 변 사이에 직각이 끼어 있나요?','직각삼각형의 빗변과 다른 한 변이 같은 합동 조건을 구분하세요.',r'$\angle OMA=\angle ONC=90^\circ$, $OA=OC$, $OM=ON$입니다.|이는 빗변과 다른 한 변이 같은 직각삼각형의 $RHS$ 합동입니다. 따라서 $\triangle OAM\cong\triangle OCN$입니다.|직각은 두 알려진 변 사이의 끼인각이 아니므로 $SAS$를 쓰는 보기 $5$가 잘못되었습니다.','두 변 사이의 각과 직각의 위치를 비교했나요?',(3,456,241,832,723))
add(4,r'그림에서 작은 호 $AC:BD=5:2$이고 작은 호 $AC$의 길이는 원주의 $\frac16$이다. 두 현 $AB,CD$의 교점을 $P$라 할 때, $\angle BPD$의 크기는?',r'$42^\circ$|$47^\circ$|$52^\circ$|$57^\circ$|$62^\circ$',1,'circle','두 현이 원 안에서 만날 때 각은 두 호의 합과 연결되나요?','원주의 비로 중심각을 구한 뒤 교차각 공식을 삼각형의 외각과 원주각으로 적용하세요.',r'호 $AC$의 중심각은 $360^\circ\times\frac16=60^\circ$입니다. 호 $BD$의 중심각은 $60^\circ\times\frac25=24^\circ$입니다.|원 안에서 교차하는 두 현의 각은 마주 보는 두 호의 중심각 합의 절반이므로 $\angle BPD=\frac{60+24}{2}^\circ=42^\circ$입니다.','원 밖 교차각의 차 공식과 혼동하지 않았나요?',(4,95,218,263,372))
add(4,r'보기에서 주어진 종류의 모든 사각형이 원에 내접한다고 보장할 수 없는 것을 고른 것은?'+ '\n'+r'ㄱ. 마름모  ㄴ. 직사각형  ㄷ. 평행사변형  ㄹ. 등변사다리꼴',r'ㄱ, ㄴ|ㄱ, ㄷ|ㄴ, ㄷ|ㄴ, ㄹ|ㄷ, ㄹ',2,'circle','한 특별한 경우가 아니라 그 종류의 모든 도형에서 성립해야 하나요?','원에 내접하는 사각형의 대각 합으로 각 도형을 판단하세요.',r'직사각형의 대각 합은 항상 $180^\circ$입니다. 등변사다리꼴도 같은 밑각과 평행선의 성질에서 대각 합이 $180^\circ$입니다.|마름모와 평행사변형은 직각인 특별한 경우를 제외하면 대각 합이 $180^\circ$가 아닙니다. 따라서 항상 내접한다고 보장하지 못하는 것은 ㄱ, ㄷ입니다.','가능한 특별한 사례와 항상 성립하는 성질을 구분했나요?',reason='원문의 항상 내접하는 사각형이 아닌 것을 모든 도형에서 내접을 보장할 수 없는 종류로 명확히 표현.')
add(4,r'직선 $PT$는 원 $O$의 접선이고 $AC$는 지름이다. $P,A,C$가 일직선 위에 있고 $\angle PCB=35^\circ$일 때, $\angle APB$의 크기는?',r'$18^\circ$|$20^\circ$|$25^\circ$|$30^\circ$|$35^\circ$',2,'circle','지름에 대한 직각과 접선이 만드는 각을 찾았나요?','원주각과 접선-현의 각을 사용해 바깥 삼각형의 두 각을 구하세요.',r'$\angle ABC=90^\circ$, $\angle ACB=35^\circ$이므로 $\angle CAB=55^\circ$입니다.|접선과 현의 각에서 $\angle PBA=35^\circ$이고 $\angle PAB=180^\circ-55^\circ=125^\circ$입니다.|$\angle APB=180^\circ-125^\circ-35^\circ=20^\circ$입니다.','연장선 쪽의 각을 내각과 구분했나요?',(4,489,181,674,339))
add(4,r'휴게소 $A$와 매표소 $C$ 사이의 거리를 알아보기 위해 놀이터 $B$에서 측량했더니 $BC=20\,m$, $\angle B=60^\circ$, $\angle C=75^\circ$였다. $AC$의 길이는?',r'$10\sqrt2\,m$|$10\sqrt3\,m$|$10\sqrt6\,m$|$20\sqrt3\,m$|$20\sqrt6\,m$',3,'ratio','나머지 꼭짓점의 각을 구할 수 있나요?','밑변의 한 끝에서 반대편 변에 수선을 내려 공통 높이를 두 삼각비로 표현하세요.',r'$\angle A=180^\circ-60^\circ-75^\circ=45^\circ$입니다.|$C$에서 $AB$에 내린 수선의 길이는 $20\sin60^\circ=10\sqrt3$이며 동시에 $AC\sin45^\circ$입니다.|따라서 $AC=\frac{10\sqrt3}{\sqrt2/2}=10\sqrt6\,m$입니다.','공통 높이를 사인으로 나눈 거리의 값과 단위는 무엇인가요?',(4,493,733,751,925),reason='정답표의 cm는 문제의 측량 거리 m와 불일치하므로 m로 교정.')
add(4,r'$AB=2\,cm$, $AC=4\,cm$, $\angle A=120^\circ$인 삼각형 $ABC$에서 $AD$는 각 $A$의 이등분선이고 $D$는 $BC$ 위에 있다. 삼각형의 넓이와 $AD$의 길이를 순서대로 바르게 짝지은 것은?',r'$2\sqrt3\,cm^2,\ \frac43\,cm$|$2\sqrt3\,cm^2,\ \frac83\,cm$|$4\sqrt3\,cm^2,\ \frac43\,cm$|$4\sqrt3\,cm^2,\ \frac83\,cm$|$2\sqrt3\,cm^2,\ 2\,cm$',1,'area','전체 넓이와 나뉜 두 삼각형 넓이가 같다는 식을 쓸 수 있나요?','전체는 두 변과 둔각으로, 부분들은 각 이등분선과 두 예각으로 넓이를 표현하세요.',r'전체 넓이는 $\frac12\times2\times4\times\sin120^\circ=2\sqrt3\,cm^2$입니다.|$AD=x$라 하면 두 작은 삼각형 넓이의 합은 $\frac12\times2x\sin60^\circ+\frac12\times4x\sin60^\circ=\frac{3\sqrt3}{2}x$입니다.|전체와 같게 놓으면 $x=\frac43\,cm$입니다.','넓이와 길이를 둘 다 구하고 순서대로 고를 수 있나요?',(5,87,210,321,300),reason='원본 16번의 두 소문항을 빠짐없이 포함하는 넓이·길이 짝 선택형으로 구성. 정답표에 누락된 두 번째 답은 독립 계산으로 보완.')
add(4,r'$AB$는 반원 $O$의 지름이고 $AD,BC,CD$는 접선이다. $AD=16\,cm$, $BC=9\,cm$일 때, 사각형 $ABCD$의 넓이는?',r'$150\,cm^2$|$240\,cm^2$|$250\,cm^2$|$300\,cm^2$|$360\,cm^2$',4,'tangent','같은 점에서 그은 두 접선 길이를 빗변에 표시할 수 있나요?','사다리꼴의 평행한 두 변의 차와 기울어진 변으로 높이를 구하세요.',r'$CD$의 접점을 $E$라 하면 $DE=DA=16$, $CE=CB=9$이므로 $CD=25\,cm$입니다.|두 수직변의 길이 차는 $7\,cm$이므로 $AB=\sqrt{25^2-7^2}=24\,cm$입니다.|사다리꼴 넓이는 $\frac{16+9}{2}\times24=300\,cm^2$입니다.','평행한 두 변이 어느 방향에 있는지 확인했나요?',(5,73,830,266,966))
add(4,r'원 $O$에서 작은 호 $AB$의 중점 $M$을 잡고 현 $MC,MD$와 현 $AB$의 교점을 각각 $P,Q$라 하자. 사각형 $PCDQ$에서 $\angle MQA$와 항상 같은 각은?',r'$\angle PCD$|$\angle CPQ$|$\angle PQD$|$\angle CDQ$|$\angle PDQ$',1,'circle','같은 두 호를 원주각 또는 현의 교차각에 연결할 수 있나요?','교차각이 보는 두 호의 합과 다른 원주각이 보는 한 호를 비교하세요.',r'$\angle MQA$는 현 $MD,AB$의 교차각이므로 그 크기는 호 $MA$와 호 $BD$의 중심각 합의 절반입니다.|호 $MA=MB$이므로 이 합은 호 $MD$의 중심각과 같습니다.|$P,C,M$이 일직선이므로 $\angle PCD=\angle MCD$이며 호 $MD$에 대한 원주각입니다. 따라서 두 각은 같습니다.','같은 호를 보는 사각형의 내각은 어느 꼭짓점에 있나요?',(5,490,243,673,424))
add(4,r'원 $O$의 두 현 $AB,CD$의 교점이 $P$이고 호 $AC$와 호 $AD$가 같다. $AC=12$, $AP=8$일 때, $PC\cdot PD$의 값은?',r'$48$|$64$|$72$|$80$|$96$',4,'power','같은 호에서 같은 현을 찾고 밑변의 중점을 잡을 수 있나요?','이등변삼각형의 높이에 대한 두 피타고라스 식을 빼서 곱을 구하세요.',r'같은 호이므로 $AC=AD=12$입니다. $CD$의 중점을 $H$, $CH=DH=t$, $PH=u$, $AH=h$라 하면 $AH\perp CD$입니다.|$h^2+t^2=12^2$, $h^2+u^2=8^2$이므로 $t^2-u^2=144-64=80$입니다.|$PC\cdot PD=(t+u)(t-u)=t^2-u^2=80$입니다.','두 식의 공통 높이를 소거하면 무엇이 남나요?',(5,472,845,664,1022))
# Final serialization and source-faithful raster extraction.
import re
PAGES={1:[1]*5+[2]*4+[3]*4+[4]*4+[5]*4+[6]*4,2:[1]*4+[2]*4+[3]*4+[4]*4+[5]*3+[6]*3+[7]*4+[8]*4,3:[1]*4+[2]*4+[3]*4+[4]*4+[5]*4+[6]*3+[7]*3,4:[1]*5+[2]*4+[3]*2+[4]*4+[5]*4}
def norm(s):
 s=re.sub(r'\\frac\s*([a-zA-Z0-9])\s*([a-zA-Z0-9])',r'\\frac{\1}{\2}',s)
 s=re.sub(r'\\frac\s*([a-zA-Z0-9])\s*(?=\{)',r'\\frac{\1}',s)
 s=s.replace(r'\frac\pi3',r'\frac{\pi}{3}')
 return s
for r in D:
 out=B/'authoring'/f'round{r}';assets=out/'assets';assets.mkdir(parents=True,exist_ok=True)
 doc=fitz.open(B/'sources'/f'round{r}'/'source.pdf')
 assert len(D[r])==len(PAGES[r])
 for i,(q,m) in enumerate(zip(D[r],M[r])):
  for k in q:q[k]=[norm(v) for v in q[k]] if isinstance(q[k],list) else norm(q[k])
  page=PAGES[r][i];m['sourcePage']=page
  # Preserve a complete original page for audit, including surrounding conditions.
  doc[page-1].get_pixmap(matrix=fitz.Matrix(1.25,1.25)).save(out/m['sourceImagePath'])
  if m['crop']:
   pn,x0,y0,x1,y1=m['crop'];doc[pn-1].get_pixmap(matrix=fitz.Matrix(3,3),clip=fitz.Rect((x0-10)/1.5,y0/1.5,(x1+10)/1.5,(y1+10)/1.5)).save(out/m['imagePath'])
 (out/'questions.json').write_text(json.dumps({'questions':D[r]},ensure_ascii=False,indent=2)+'\n')
 (out/'manifest.json').write_text(json.dumps(dict(round=r,unitId='reg_1781420075936_chap_1781420292103_unit_'+U[r-1],sourceTitle=['중3 모의고사 원본1회','중3 수학 원본5회 (별도 해설지 대조)','중3 모의고사 원본6회','중3 모의고사 원본7회'][r-1],questions=M[r]),ensure_ascii=False,indent=2)+'\n')
 print('round',r,'questions',len(D[r]),'figures',sum(bool(x['imagePath']) for x in M[r]))
